    "file.changed",
    "turn.stop",
    "compact.before",
    "compact.after",
    "session.end",
}
_SKILL_PROMPT = re.compile(r"(?<![A-Za-z0-9_-])(?:\$\s*|/)code-knowledge-builder(?![A-Za-z0-9_-])", re.IGNORECASE)
_SKILL_METADATA_KEYS = {
    "active_skill",
    "active_skills",
    "applied_skill",
    "applied_skills",
    "command_name",
    "commandname",
    "skill",
    "skill_name",
