        value: dict[str, Any] = {"command": command, "timeout": timeout}
        if matcher:
            value["matcher"] = matcher
        return value

    return {
        "version": 1,
        "hooks": {
            "sessionStart": [handler()],
            "beforeSubmitPrompt": [handler("UserPromptSubmit", 20)],
            "postToolUse": [handler("Shell|Write|Delete|MCP:.*")],
            "postToolUseFailure": [handler("Shell|Write|Delete|MCP:.*")],
            "afterFileEdit": [handler("Write")],
            "afterAgentResponse": [handler()],
            "preCompact": [handler()],
            "stop": [handler("Stop", 15)],
            "sessionEnd": [handler(timeout=3)],
        },
    }


def _opencode_stable_plugin(python: Path, ckb: Path, registry: Path) -> str:
    command_args = ["-X", "utf8", str(ckb), "automation", "hook", "--harness", "opencode", "--registry", str(registry)]
    return f'''import {{ spawnSync }} from "node:child_process"

const PYTHON = {json.dumps(str(python))}
const ARGS = {json.dumps(command_args)}

function value(object, keys) {{
  if (!object || typeof object !== "object") return undefined
  for (const key of keys) if (object[key] !== undefined && object[key] !== null) return object[key]
  for (const child of Object.values(object)) {{
    const found = value(child, keys)
    if (found !== undefined) return found
  }}
}}

function text(object) {{
  if (typeof object === "string") return object
  if (Array.isArray(object)) return object.map(text).filter(Boolean).join("\\n")
  if (!object || typeof object !== "object") return ""
  if (typeof object.text === "string") return object.text
  for (const key of ["content", "parts", "message", "delta"]) {{
    const found = text(object[key])
    if (found) return found
  }}
  return ""
}}

function emit(payload) {{
  try {{
    const event = {{ ...payload, harness_pid: process.pid }}
    spawnSync(PYTHON, ARGS, {{ input: JSON.stringify(event), encoding: "utf8", timeout: payload?.ckb_skill_applied ? 20000 : 8000, windowsHide: true }})
  }} catch {{}}
}}

export const CodeKnowledgeBuilderSync = async ({{ directory, worktree }}) => {{
  const cwd = worktree || directory || process.cwd()
  const assistants = new Map()
  return {{
    event: async ({{ event }}) => {{
      const data = event?.properties ?? event?.data ?? event ?? {{}}
      const info = data?.info ?? data
      const sessionID = String(value(info, ["sessionID", "sessionId", "session_id", "id"]) ?? "session-unknown")
      const base = {{ session_id: sessionID, cwd }}
      if (event?.type === "session.created") emit({{ ...base, hook_event_name: "SessionStart", source: "startup", event_id: `session-created:${{sessionID}}` }})
      if (event?.type === "message.updated") {{
        const role = String(value(info, ["role"]) ?? "").toLowerCase()
        const body = text(info)
        const messageID = String(value(info, ["messageID", "messageId", "id"]) ?? "")
        if (role === "user") emit({{ ...base, hook_event_name: "UserPromptSubmit", prompt: body, event_id: `message:${{messageID}}` }})
        if (role === "assistant") {{
          assistants.set(sessionID, body)
          emit({{ ...base, hook_event_name: "AssistantMessage", assistant_message: body, event_id: `message:${{messageID}}` }})
        }}
      }}
      if (event?.type === "command.executed") {{
        const commandName = String(value(data, ["command", "commandName", "name"]) ?? "")
        if (commandName.replace(/^[$/]/, "") === "code-knowledge-builder") emit({{ ...base, hook_event_name: "SkillApplied", skill_name: "code-knowledge-builder", ckb_skill_applied: true, event_id: `skill:${{sessionID}}:${{commandName}}` }})
      }}
      if (event?.type === "file.edited") emit({{ ...base, hook_event_name: "FileChanged", file_path: value(data, ["file", "filePath", "path"]), event: "change" }})
      if (event?.type === "session.compacted") emit({{ ...base, hook_event_name: "PostCompact", trigger: "auto" }})
      if (event?.type === "session.idle") emit({{ ...base, hook_event_name: "Stop", last_assistant_message: assistants.get(sessionID) ?? "", stop_hook_active: false }})
      if (event?.type === "session.deleted") emit({{ ...base, hook_event_name: "SessionEnd", reason: "other" }})
    }},
    "tool.execute.after": async (input, output) => {{
      emit({{
        session_id: String(input?.sessionID ?? input?.sessionId ?? "session-unknown"),
        cwd,
        hook_event_name: "PostToolUse",
        tool_name: String(input?.tool ?? "unknown"),
        tool_use_id: String(input?.callID ?? input?.toolCallID ?? input?.id ?? ""),
        tool_input: input?.args ?? input?.input ?? input,
        tool_response: output,
        status: "completed",
      }})
    }},
  }}
}}
'''


def _opencode_v2_plugin(python: Path, ckb: Path, registry: Path) -> str:
    command_args = ["-X", "utf8", str(ckb), "automation", "hook", "--harness", "opencode-v2", "--registry", str(registry)]
    return f'''import {{ spawnSync }} from "node:child_process"
import {{ Plugin }} from "@opencode-ai/plugin"

const PYTHON = {json.dumps(str(python))}
const ARGS = {json.dumps(command_args)}

function emit(payload) {{
  try {{
    const event = {{ ...payload, harness_pid: process.pid }}
    spawnSync(PYTHON, ARGS, {{ input: JSON.stringify(event), encoding: "utf8", timeout: payload?.ckb_skill_applied ? 20000 : 8000, windowsHide: true }})
  }} catch {{}}
}}

function messageText(message) {{
  const parts = message?.parts ?? message?.content ?? []
  if (typeof parts === "string") return parts
  return Array.isArray(parts) ? parts.map((part) => typeof part === "string" ? part : part?.text ?? "").filter(Boolean).join("\\n") : ""
}}

function unwrapMessages(value) {{
  if (Array.isArray(value)) return value
  if (Array.isArray(value?.data)) return value.data
  if (Array.isArray(value?.messages)) return value.messages
  return []
}}

function eventSessionID(event) {{
  return String(event?.sessionID ?? event?.properties?.sessionID ?? event?.data?.sessionID ?? "session-unknown")
}}

function eventCwd(event) {{
  return String(event?.cwd ?? event?.location?.directory ?? event?.properties?.cwd ?? event?.data?.cwd ?? process.cwd())
}}

export default Plugin.define({{
  id: "code-knowledge-builder.sync",
  setup: async (ctx) => {{
    const seenSessions = new Set()
    const sessionCwds = new Map()
    await ctx.session.hook("context", (event) => {{
      const sessionID = String(event.sessionID ?? "session-unknown")
      const cwd = eventCwd(event)
      sessionCwds.set(sessionID, cwd)
      if (!seenSessions.has(sessionID)) {{
        seenSessions.add(sessionID)
        emit({{ session_id: sessionID, cwd, hook_event_name: "SessionStart", source: "startup", event_id: `session:${{sessionID}}` }})
      }}
      const messages = Array.isArray(event.messages) ? event.messages : []
      const latest = [...messages].reverse().find((item) => item?.role === "user")
      if (latest) emit({{ session_id: sessionID, cwd, hook_event_name: "UserPromptSubmit", prompt: messageText(latest), event_id: `message:${{latest.id ?? latest.messageID ?? "latest"}}` }})
    }})
    await ctx.tool.hook("execute.after", (event) => {{
      emit({{
        session_id: String(event.sessionID ?? "session-unknown"),
        cwd: String(event.cwd ?? process.cwd()),
        hook_event_name: "PostToolUse",
        tool_name: String(event.tool ?? "unknown"),
        tool_use_id: String(event.toolCallID ?? event.callID ?? ""),
        tool_input: event.input,
        tool_response: event.status === "error" ? event.error : event.result,
        output_paths: event.outputPaths ?? [],
        status: event.status ?? "completed",
      }})
    }})
    const controller = new AbortController()
    void (async () => {{
      try {{
        for await (const event of ctx.event.subscribe({{ signal: controller.signal }})) {{
          const sessionID = eventSessionID(event)
          const cwd = eventCwd(event)
          if (event.type === "command.executed") {{
            const commandName = String(event?.command ?? event?.properties?.command ?? event?.data?.command ?? "")
            if (commandName.replace(/^[$/]/, "") === "code-knowledge-builder") emit({{ session_id: sessionID, cwd, hook_event_name: "SkillApplied", skill_name: "code-knowledge-builder", ckb_skill_applied: true, event_id: `skill:${{sessionID}}:${{commandName}}` }})
          }}
          if (["session.execution.succeeded", "session.execution.succeeded.1", "session.idle"].includes(event.type)) {{
            const messages = unwrapMessages(await ctx.session.context({{ sessionID }}))
            const latest = [...messages].reverse().find((item) => item?.role === "assistant")
            emit({{ session_id: sessionID, cwd, hook_event_name: "Stop", last_assistant_message: messageText(latest), stop_hook_active: false, event_id: `stop:${{sessionID}}:${{latest?.id ?? event.id ?? event.type}}` }})
          }}
          if (["session.execution.failed", "session.execution.failed.1"].includes(event.type)) emit({{ session_id: sessionID, cwd, hook_event_name: "StopFailure", last_assistant_message: String(event.error?.message ?? event.error ?? "OpenCode 执行失败。"), event_id: `stop-failed:${{sessionID}}:${{event.id ?? event.type}}` }})
          if (event.type === "session.deleted") emit({{ session_id: sessionID, cwd, hook_event_name: "SessionEnd", reason: "other", event_id: `session-end:${{sessionID}}` }})
          if (event.type === "session.compacted") emit({{ session_id: sessionID, cwd, hook_event_name: "PostCompact", trigger: "auto", event_id: `compact:${{sessionID}}:${{event.id ?? "auto"}}` }})
        }}
      }} catch {{}}
    }})()
    return () => {{
      for (const sessionID of seenSessions) emit({{ session_id: sessionID, cwd: sessionCwds.get(sessionID) ?? process.cwd(), hook_event_name: "SessionEnd", reason: "plugin-unload", event_id: `plugin-unload:${{sessionID}}` }})
      controller.abort()
    }}
  }},
}})
'''


def _generic_schema() -> dict[str, Any]:
    return {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "$id": "https://code-knowledge-builder.local/automation-event.schema.json",
        "title": "Code Knowledge Builder canonical automation event",
        "type": "object",
        "required": ["canonical_type", "session_id", "cwd"],
        "properties": {
            "canonical_type": {
                "enum": [
                    "skill.applied",
                    "session.start",
                    "turn.prompt",
                    "turn.assistant",
                    "tool.result",
                    "file.changed",
                    "turn.stop",
                    "compact.before",
                    "compact.after",
                    "session.end",
                ]
            },
            "event_id": {"type": "string", "minLength": 1},
            "session_id": {"type": "string", "minLength": 1},
            "turn_id": {"type": "string"},
            "cwd": {"type": "string", "minLength": 1},
            "prompt": {"type": "string"},
            "assistant_message": {"type": "string"},
            "tool_name": {"type": "string"},
            "tool_use_id": {"type": "string"},
            "tool_input": {},
            "tool_output": {},
            "changed_paths": {"type": "array", "items": {"type": "string"}},
            "skill_name": {"type": "string", "const": "code-knowledge-builder"},
            "ckb_skill_applied": {"type": "boolean", "const": True},
            "harness_pid": {"type": "integer", "minimum": 1},
        },
        "additionalProperties": True,
    }


def render_integration(
    harness: str,
    destination: Path,
    python: Path | None = None,
    ckb: Path | None = None,
    registry: Path | None = None,
    *,
    force: bool = False,
) -> dict[str, Any]:
    from .management_agent import binding_schema, harness_capabilities

    if harness not in SUPPORTED_HARNESSES:
        raise CkbError(f"unsupported integration harness: {harness}")
    destination = destination.resolve()
    python = (python or Path(sys.executable)).expanduser().resolve()
    ckb = (ckb or Path(__file__).resolve().parents[1] / "ckb.py").expanduser().resolve()
    registry = (registry or Path.home() / ".ckb" / "automation-registry.json").expanduser().resolve()
    if not python.is_file():
        raise CkbError(f"integration Python executable is missing: {python}")
    if not ckb.is_file():
        raise CkbError(f"integration CKB entrypoint is missing: {ckb}")
    if destination.exists() and any(destination.iterdir()) and not force:
        raise CkbError(f"integration destination is not empty: {destination}; use --force to replace generated files")
    destination.mkdir(parents=True, exist_ok=True)
    posix, windows = _commands(python, ckb, harness, registry)
    windows_args = [str(python), "-X", "utf8", str(ckb), "automation", "hook", "--harness", harness, "--registry", str(registry)]
    powershell = _powershell_command(python, ckb, harness, registry)
    files: list[Path] = []

    def write(relative: str, value: str | dict[str, Any]) -> Path:
        path = destination / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        text = json.dumps(value, ensure_ascii=False, indent=2) + "\n" if isinstance(value, dict) else value
        path.write_text(text, encoding="utf-8", newline="\n")
        files.append(path)
        return path

    if harness == "codex":
        windows, windows_bridge = _codex_windows_bridge(destination, windows_args)
        write(
            ".codex-plugin/plugin.json",
            {
                "name": "code-knowledge-builder-sync",
                "version": INTEGRATION_VERSION,
                "description": "仅在会话明确应用 code-knowledge-builder Skill 后，同步已登记项目的 Codex 会话和修改证据。",
                "author": {"name": "Code Knowledge Builder"},
                "interface": {
                    "displayName": "Code Knowledge Builder Sync",
                    "shortDescription": "同步明确应用 CKB Skill 的项目会话",
                    "longDescription": "会话明确应用 code-knowledge-builder Skill 后，把 Codex 生命周期事件写入脱敏机器队列，并等待 Agent 中文审阅后再进入人类知识库。",
                    "developerName": "Code Knowledge Builder",
                    "category": "Productivity",
                    "capabilities": ["Read", "Write"],
                    "defaultPrompt": "检查当前项目的 Code Knowledge Builder 自动同步状态。",
                },
            },
        )
        write("hooks/ckb-hook.cmd", windows_bridge)
        write("hooks/hooks.json", _codex_hooks(posix, windows))
    elif harness == "claude":
        command = windows if _looks_windows(python) else posix
        write(".claude/settings.json", _claude_hooks(command))
    elif harness == "opencode":
        write(".opencode/plugins/code-knowledge-builder-sync.mjs", _opencode_stable_plugin(python, ckb, registry))
    elif harness == "opencode-v2":
        write(".opencode/plugins/code-knowledge-builder-sync-v2.mjs", _opencode_v2_plugin(python, ckb, registry))
    elif harness == "dsh":
        # The current DSH Codex bridge intentionally reads `command` and ignores
        # Codex's `commandWindows` extension, so stamp the platform command into
        # both fields when rendering on Windows.
        dsh_command = windows if _looks_windows(python) else posix
        write("hooks.json", _codex_hooks(dsh_command, dsh_command, dsh_subset=True))
        config_path = (destination / "hooks.json").as_posix()
        write(
            "cordis.yml.fragment",
            "- dsh-hooks-codex:\n"
            f"    configPath: {json.dumps(config_path)}\n"
            "    model: ckb-sync\n",
        )
    elif harness == "gemini":
        command = windows if _looks_windows(python) else posix
        write(".gemini/settings.json", _gemini_hooks(command))
    elif harness == "copilot":
        write(".github/hooks/code-knowledge-builder.json", _copilot_hooks(posix, powershell))
    elif harness == "cursor":
        command = windows if _looks_windows(python) else posix
        write(".cursor/hooks.json", _cursor_hooks(command))
    else:
        write("automation-event.schema.json", _generic_schema())
        write("management-binding.schema.json", binding_schema())
        write(
            "example-event.json",
            {
                "canonical_type": "skill.applied",
                "event_id": "HARNESS_EVENT_ID",
                "session_id": "HARNESS_SESSION_ID",
                "cwd": "/absolute/project/path",
                "skill_name": "code-knowledge-builder",
                "ckb_skill_applied": True,
            },
        )
        write(
            "example-management-binding.json",
            {
                "schema_version": 1,
                "conversation_id": "HARNESS_CONVERSATION_ID",
                "harness_id": "generic",
                "workspace_root": "/absolute/workspace/path",
                "repo_root": "/absolute/workspace/path/source",
                "knowledge_base": "/absolute/workspace/path/knowledge-base",
                "integration_branch": "INTEGRATION_BRANCH",
                "notification_policy": "none",
            },
        )
    manifest = {
        "schema_version": 1,
        "status": "rendered",
        "integration_version": INTEGRATION_VERSION,
        "harness": harness,
        "python": str(python),
        "ckb": str(ckb),
        "registry": str(registry),
        "project_opt_in_required": True,
        "session_skill_activation_required": True,
        "required_skill": "code-knowledge-builder",
        "transcript_parsing": False,
        "management_capabilities": harness_capabilities(harness),
        "retrieval_contract": harness_retrieval_contract(harness),
        "session_stdio_capability": {
            "activation": "exact-skill-application",
            "session_end": harness not in {"dsh"},
            "parent_monitor": (
                "native-plugin-process"
                if harness in {"opencode", "opencode-v2"}
                else "caller-supplied"
                if harness == "generic"
                else "unavailable"
            ),
            "degraded": harness not in {"opencode", "opencode-v2"},
        },
        "files": [str(path.relative_to(destination).as_posix()) for path in files],
    }
    manifest_path = write("integration.json", manifest)
    return {**manifest, "destination": str(destination), "manifest": str(manifest_path)}

from __future__ import annotations

import hashlib
import json
import os
import re
import shutil
import subprocess
import tempfile
import time
import uuid
from pathlib import Path
from typing import Any, Iterable


EXIT_OK = 0
EXIT_INPUT = 2
EXIT_DEPENDENCY = 3
EXIT_REVIEW = 4
EXIT_AUDIT = 5
EXIT_STALE = 6


class CkbError(RuntimeError):
    exit_code = EXIT_INPUT


class DependencyError(CkbError):
    exit_code = EXIT_DEPENDENCY


class ReviewRequired(CkbError):
    exit_code = EXIT_REVIEW


class AuditError(CkbError):
    exit_code = EXIT_AUDIT


class StaleSourceError(CkbError):
    exit_code = EXIT_STALE


def utc_now() -> str:
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


def stable_id(prefix: str, *parts: Any) -> str:
    text = "\0".join(str(part) for part in parts)
    value = uuid.uuid5(uuid.NAMESPACE_URL, text).hex
    return f"{prefix}-{value}"


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def json_load(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8-sig"))


def json_write(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".tmp")
    temporary.write_text(
        json.dumps(value, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
        newline="\n",
    )
    os.replace(temporary, path)


def background_process_options(*, visible: bool = False) -> dict[str, Any]:
    """Hide non-interactive Windows child consoles without changing I/O semantics."""
    if visible or os.name != "nt":
        return {}
    creation_flag = getattr(subprocess, "CREATE_NO_WINDOW", 0)
    return {"creationflags": creation_flag} if creation_flag else {}


def run(
    command: list[str],
    *,
    cwd: Path | None = None,
    env: dict[str, str] | None = None,
    check: bool = False,
    timeout: int | None = None,
    visible: bool = False,
) -> subprocess.CompletedProcess[str]:
    completed = subprocess.run(
        command,
        cwd=str(cwd) if cwd else None,
        env=env,
        text=True,
        encoding="utf-8",
        errors="replace",
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        timeout=timeout,
        **background_process_options(visible=visible),
    )
    if check and completed.returncode:
        detail = (completed.stderr or completed.stdout).strip()
        raise CkbError(f"command failed ({completed.returncode}): {' '.join(command)}\n{detail}")
    return completed


def command_version(executable: str, args: Iterable[str] = ("--version",)) -> dict[str, Any]:
    resolved = shutil.which(executable)
    if not resolved:
        return {"status": "missing", "command": executable, "path": None, "version": None}
    completed = run([resolved, *args], timeout=20)
    text = (completed.stdout or completed.stderr).strip().splitlines()
    return {
        "status": "ready" if completed.returncode == 0 else "broken",
        "command": executable,
        "path": str(Path(resolved).resolve()),
        "version": text[0] if text else None,
        "exit_status": completed.returncode,
    }


def clear_markers(output: Path) -> None:
    for name in (
        ".pending-agent-review",
        ".failed",
        ".complete",
        ".machine.complete",
        ".human.complete",
    ):
        (output / name).unlink(missing_ok=True)


def write_marker(output: Path, name: str, payload: dict[str, Any]) -> None:
    clear_markers(output)
    json_write(output / name, payload)


def safe_title(text: str, limit: int = 120) -> str:
    value = re.sub(r"[\\/:*?\"<>|\[\]]+", "-", text).strip(" .-")
    return (value[:limit] or "untitled").strip()


def path_inside(path: Path, root: Path) -> bool:
    try:
        path.resolve().relative_to(root.resolve())
        return True
    except ValueError:
        return False


def safe_rmtree(path: Path, root: Path) -> None:
    """Remove one verified descendant without ever accepting the root itself."""
    resolved_path = path.resolve()
    resolved_root = root.resolve()
    if resolved_path == resolved_root or not path_inside(resolved_path, resolved_root):
        raise CkbError(f"recursive removal target is outside its declared root: {resolved_path}")
    if resolved_path.exists():
        shutil.rmtree(resolved_path)


def temp_directory(prefix: str = "ckb-"):
    return tempfile.TemporaryDirectory(prefix=prefix)

"""Deterministic, location-anchored human feedback for knowledge pages.

The fixed source graph remains generator-owned.  Feedback is stored as machine
JSON under ``workspace-meta`` and projected as small, frontmatter-free Chinese
Markdown records into both human vaults.  Resolved feedback is archived rather
than deleted.
"""

from __future__ import annotations

from collections import defaultdict
import datetime as dt
from pathlib import Path, PurePosixPath
import re
from typing import Any

from .common import CkbError, json_load, json_write, path_inside, safe_title, utc_now


FEEDBACK_SCHEMA_VERSION = 1
FEEDBACK_DIRECTORIES = ("feedback/open", "feedback/resolved")
SEVERITIES = ("error", "warn", "suggest", "info")
SOURCES = ("manual", "obsidian-plugin", "web-viewer")
DECISIONS = ("accepted", "partial", "rejected", "deferred")
SEVERITY_ORDER = {value: index for index, value in enumerate(SEVERITIES)}
STATUS_DIRECTORY = {"open": "open", "resolved": "resolved"}
CHINESE_RE = re.compile(r"[\u3400-\u9fff]")
LONG_HEX = re.compile(r"(?<![0-9A-Fa-f])[0-9A-Fa-f]{40,}(?![0-9A-Fa-f])")


def _contains_chinese(value: Any, minimum_han: int = 2) -> bool:
    return isinstance(value, str) and len(CHINESE_RE.findall(value)) >= minimum_han


def prepare_feedback_store(output: Path) -> dict[str, Any]:
    """Create only the feedback-owned directories for a finalized Markdown KB."""
    output = output.resolve()
    metadata = output / "workspace-meta/feedback"
    for status in STATUS_DIRECTORY.values():
        (metadata / status).mkdir(parents=True, exist_ok=True)
    vaults = []
    for name in ("markdown", "human"):
        root = output / name
        if root.is_dir():
            for relative in FEEDBACK_DIRECTORIES:
                (root / relative).mkdir(parents=True, exist_ok=True)
            vaults.append(str(root.resolve()))
    return {
        "schema_version": FEEDBACK_SCHEMA_VERSION,
        "status": "ready",
        "metadata_root": str(metadata.resolve()),
        "vaults": vaults,
    }


def _canonical_relative_target(output: Path, target: Path) -> tuple[str, Path, Path]:
    output = output.resolve()
    human = output / "human"
    markdown = output / "markdown"
    if not human.is_dir() or not markdown.is_dir():
        raise CkbError("feedback requires finalized human and markdown knowledge roots")
    raw = str(target).replace("\\", "/")
    candidate = Path(target)
    if candidate.is_absolute():
        resolved = candidate.resolve()
        if path_inside(resolved, human):
            relative = resolved.relative_to(human).as_posix()
        elif path_inside(resolved, markdown):
            relative = resolved.relative_to(markdown).as_posix()
        else:
            raise CkbError("feedback target must be inside OUTPUT/human or OUTPUT/markdown")
    else:
        for prefix in ("human/", "markdown/"):
            if raw.startswith(prefix):
                raw = raw[len(prefix) :]
                break
        pure = PurePosixPath(raw)
        if pure.is_absolute() or ".." in pure.parts:
            raise CkbError("feedback target must be a knowledge-root relative path")
        relative = pure.as_posix().lstrip("./")
    if not relative or relative.startswith("feedback/") or not relative.endswith(".md"):
        raise CkbError("feedback target must be a non-feedback Markdown knowledge page")
    human_target = human / relative
    markdown_target = markdown / relative
    if not human_target.is_file() or not markdown_target.is_file():
        raise CkbError(f"feedback target is missing from the mirrored human knowledge roots: {relative}")
    if human_target.read_bytes() != markdown_target.read_bytes():
        raise CkbError(f"feedback target differs between human and markdown roots: {relative}")
    return relative, human_target, markdown_target


def _read_chinese_body(path: Path, label: str) -> str:
    if not path.is_file():
        raise CkbError(f"{label} body does not exist: {path}")
    value = path.read_text(encoding="utf-8-sig").strip()
    if not value:
        raise CkbError(f"{label} body must not be empty")
    if not _contains_chinese(value):
        raise CkbError(f"{label} narrative must use Simplified Chinese")
    if value.startswith("---\n") or LONG_HEX.search(value):
        raise CkbError(f"{label} body must omit frontmatter and hash-like identifiers")
    return value


def _line_selection(text: str, start_line: int, end_line: int) -> tuple[str, str, str]:
    if start_line < 1 or end_line < start_line:
        raise CkbError("feedback line range must be a positive inclusive range")
    lines = text.splitlines(keepends=True)
    if end_line > len(lines):
        raise CkbError(f"feedback line range exceeds target length: {end_line}>{len(lines)}")
    start_offset = sum(len(value) for value in lines[: start_line - 1])
    end_offset = sum(len(value) for value in lines[:end_line])
    anchor_text = text[start_offset:end_offset]
    if not anchor_text:
        raise CkbError("feedback selection must not be empty")
    return text[max(0, start_offset - 80) : start_offset], anchor_text, text[end_offset : end_offset + 80]


def _next_feedback_id(output: Path) -> str:
    prefix = dt.datetime.now(dt.timezone.utc).strftime("feedback-%Y%m%d-%H%M%S")
    existing = {
        path.stem
        for status in STATUS_DIRECTORY.values()
        for path in (output / "workspace-meta/feedback" / status).glob(f"{prefix}-*.json")
    }
    index = 1
    while f"{prefix}-{index:02d}" in existing:
        index += 1
    return f"{prefix}-{index:02d}"


def _title_of(path: Path) -> str:
    text = path.read_text(encoding="utf-8-sig")
    first = text.splitlines()[0] if text else ""
    return first.removeprefix("# ").strip() or path.stem


def _blockquote(value: str) -> str:
    lines = value.rstrip("\n").splitlines() or [""]
    return "\n".join("> " + line for line in lines)


def _visible_feedback(record: dict[str, Any]) -> str:
    severity_names = {"error": "错误", "warn": "警告", "suggest": "建议", "info": "说明"}
    status_names = {"open": "待处理", "resolved": "已归档"}
    source_names = {"manual": "手动", "obsidian-plugin": "Obsidian", "web-viewer": "本地查看器"}
    decision_names = {"accepted": "采纳", "partial": "部分采纳", "rejected": "不采纳", "deferred": "暂缓"}
    sections = [
        f"# {record['title']}",
        "",
        "标签：#类型/反馈",
        "",
        f"状态：{status_names[record['status']]}",
        f"严重程度：{severity_names[record['severity']]}",
        f"目标：[[{record['target_title']}]]（`{record['target']}` 第 {record['target_lines'][0]}–{record['target_lines'][1]} 行）",
        f"来源：{source_names[record['source']]}，提交者 `{record['author']}`",
        "",
        "## 反馈内容",
        "",
        record["comment"].strip(),
        "",
        "## 锚点摘录",
        "",
        _blockquote(record["anchor_text"]),
    ]
    if record.get("decision"):
        sections.extend(
            [
                "",
                "## 处理结果",
                "",
                f"决议：{decision_names[record['decision']]}。",
                "",
                str(record.get("resolution") or "").strip(),
            ]
        )
        if record.get("applied_record"):
            sections.extend(["", f"落实记录：`{record['applied_record']}`"])
    return "\n".join(sections).rstrip() + "\n"


def _record_path(output: Path, status: str, feedback_id: str) -> Path:
    return output / "workspace-meta/feedback" / STATUS_DIRECTORY[status] / f"{feedback_id}.json"


def _visible_relative(status: str, feedback_id: str) -> Path:
    return Path("feedback") / STATUS_DIRECTORY[status] / f"{feedback_id}.md"


def _write_visible_mirrors(output: Path, record: dict[str, Any]) -> list[str]:
    text = _visible_feedback(record)
    relative = _visible_relative(record["status"], record["id"])
    paths = []
    for root_name in ("markdown", "human"):
        path = output / root_name / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8", newline="\n")
        paths.append(str(path.resolve()))
    return paths


def create_feedback(
    output: Path,
    target: Path,
    start_line: int,
    end_line: int,
    comment_path: Path,
    severity: str,
    author: str,
    source: str,
) -> dict[str, Any]:
    output = output.resolve()
    if severity not in SEVERITIES:
        raise CkbError(f"feedback severity must be one of: {list(SEVERITIES)}")
    if source not in SOURCES:
        raise CkbError(f"feedback source must be one of: {list(SOURCES)}")
    if not author.strip():
        raise CkbError("feedback author must not be empty")
    prepare_feedback_store(output)
    relative, human_target, _ = _canonical_relative_target(output, target)
    target_text = human_target.read_text(encoding="utf-8-sig")
    before, anchor, after = _line_selection(target_text, start_line, end_line)
    comment = _read_chinese_body(comment_path.resolve(), "feedback")
    feedback_id = _next_feedback_id(output)
    target_title = _title_of(human_target)
    created_at = utc_now()
    record = {
        "schema_version": FEEDBACK_SCHEMA_VERSION,
        "id": feedback_id,
        "status": "open",
        "target": relative,
        "target_title": target_title,
        "title": f"关于 {target_title} 的反馈（{created_at.replace('T', ' ').removesuffix('Z')} UTC，第 {feedback_id.rsplit('-', 1)[1]} 条）",
        "target_lines": [start_line, end_line],
        "anchor_before": before,
        "anchor_text": anchor,
        "anchor_after": after,
        "severity": severity,
        "author": author.strip(),
        "source": source,
        "created_at_utc": created_at,
        "comment": comment,
        "decision": None,
        "resolution": None,
        "applied_record": None,
        "resolved_at_utc": None,
    }
    json_write(_record_path(output, "open", feedback_id), record)
    record["visible_files"] = _write_visible_mirrors(output, record)
    result = {**record, "anchor": locate_feedback(output, feedback_id)["anchor"]}
    audit = audit_feedback(output)
    if audit["status"] != "passed":
        raise CkbError(f"feedback audit failed after create: {audit['errors'][:10]}")
    return result


def _load_feedback(output: Path, feedback_id: str) -> tuple[dict[str, Any], Path]:
    if not re.fullmatch(r"feedback-\d{8}-\d{6}-\d{2,}", feedback_id):
        raise CkbError("feedback identifier has an invalid shape")
    matches = [path for status in STATUS_DIRECTORY for path in [_record_path(output, status, feedback_id)] if path.is_file()]
    if len(matches) != 1:
        raise CkbError(f"feedback identifier must resolve to exactly one record: {feedback_id}")
    return json_load(matches[0]), matches[0]


def _all_offsets(text: str, needle: str) -> list[int]:
    offsets = []
    start = 0
    while needle:
        value = text.find(needle, start)
        if value < 0:
            break
        offsets.append(value)
        start = value + 1
    return offsets


def _offset_lines(text: str, start: int, end: int) -> list[int]:
    return [text.count("\n", 0, start) + 1, text.count("\n", 0, max(start, end - 1)) + 1]


def _locate_anchor(text: str, record: dict[str, Any]) -> dict[str, Any]:
    start_line, end_line = [int(value) for value in record["target_lines"]]
    lines = text.splitlines(keepends=True)
    if 1 <= start_line <= end_line <= len(lines):
        start = sum(len(value) for value in lines[: start_line - 1])
        end = sum(len(value) for value in lines[:end_line])
        if record["anchor_text"] in text[start:end]:
            return {"status": "line-range", "current_lines": [start_line, end_line], "match_count": 1}
    offsets = _all_offsets(text, str(record["anchor_text"]))
    if len(offsets) == 1:
        start = offsets[0]
        return {
            "status": "unique-text",
            "current_lines": _offset_lines(text, start, start + len(record["anchor_text"])),
            "match_count": 1,
        }
    if len(offsets) > 1:
        window = str(record["anchor_before"]) + str(record["anchor_text"]) + str(record["anchor_after"])
        windows = _all_offsets(text, window)
        if len(windows) == 1:
            start = windows[0] + len(record["anchor_before"])
            return {
                "status": "anchor-window",
                "current_lines": _offset_lines(text, start, start + len(record["anchor_text"])),
                "match_count": len(offsets),
            }
    return {"status": "stale", "current_lines": None, "match_count": len(offsets)}


def locate_feedback(output: Path, feedback_id: str) -> dict[str, Any]:
    output = output.resolve()
    record, path = _load_feedback(output, feedback_id)
    relative, human_target, _ = _canonical_relative_target(output, Path(str(record["target"])))
    anchor = _locate_anchor(human_target.read_text(encoding="utf-8-sig"), record)
    return {
        "schema_version": FEEDBACK_SCHEMA_VERSION,
        "status": "passed" if anchor["status"] != "stale" else "stale",
        "feedback_id": feedback_id,
        "feedback_status": record["status"],
        "target": relative,
        "record": str(path.resolve()),
        "anchor": anchor,
    }


def _canonical_applied_record(output: Path, path: Path | None) -> str | None:
    if path is None:
        return None
    resolved = path.resolve()
    if not resolved.is_file() or not path_inside(resolved, output.resolve()):
        raise CkbError("applied record must be an existing file inside the knowledge output")
    relative = resolved.relative_to(output.resolve())
    if len(relative.parts) < 3 or relative.parts[0] not in {"human", "markdown"}:
        raise CkbError("applied record must point to a reviewed human knowledge note")
    note_directories = {"analysis", "changes", "pitfalls", "experiments", "sessions"}
    if relative.parts[1] not in note_directories or resolved.suffix.casefold() != ".md":
        raise CkbError("applied record must point to an analysis, change, pitfall, experiment, or session note")
    note_relative = Path(*relative.parts[1:])
    human = output / "human" / note_relative
    markdown = output / "markdown" / note_relative
    if not human.is_file() or not markdown.is_file() or human.read_bytes() != markdown.read_bytes():
        raise CkbError("applied record must have byte-identical human and markdown note mirrors")
    title = _title_of(human)
    metadata = output / "workspace-meta/notes" / f"{safe_title(title)}.json"
    if not metadata.is_file():
        raise CkbError("applied record metadata is missing; create the note through record")
    value = json_load(metadata)
    if value.get("status") != "agent-reviewed" or value.get("title") != title:
        raise CkbError("applied record must have agent-reviewed metadata")
    return relative.as_posix()


def resolve_feedback(
    output: Path,
    feedback_id: str,
    decision: str,
    resolution_path: Path,
    applied_record: Path | None = None,
) -> dict[str, Any]:
    output = output.resolve()
    if decision not in DECISIONS:
        raise CkbError(f"feedback decision must be one of: {list(DECISIONS)}")
    resolution = _read_chinese_body(resolution_path.resolve(), "feedback resolution")
    record, source_path = _load_feedback(output, feedback_id)
    if record.get("status") != "open":
        raise CkbError("only open feedback can receive a new decision")
    applied = _canonical_applied_record(output, applied_record)
    if decision in {"accepted", "partial"} and not applied:
        raise CkbError("accepted or partial feedback requires --applied-record with verified implementation evidence")
    anchor = locate_feedback(output, feedback_id)["anchor"]
    record["decision"] = decision
    record["resolution"] = resolution
    record["applied_record"] = applied
    record["resolution_anchor"] = anchor
    record["resolved_at_utc"] = utc_now() if decision != "deferred" else None
    if decision == "deferred":
        json_write(source_path, record)
        record["visible_files"] = _write_visible_mirrors(output, record)
        audit = audit_feedback(output)
        if audit["status"] != "passed":
            raise CkbError(f"feedback audit failed after defer: {audit['errors'][:10]}")
        return {**record, "anchor": anchor}
    record["status"] = "resolved"
    destination = _record_path(output, "resolved", feedback_id)
    json_write(destination, record)
    source_path.unlink()
    old_relative = _visible_relative("open", feedback_id)
    for root_name in ("markdown", "human"):
        (output / root_name / old_relative).unlink(missing_ok=True)
    record["visible_files"] = _write_visible_mirrors(output, record)
    audit = audit_feedback(output)
    if audit["status"] != "passed":
        raise CkbError(f"feedback audit failed after resolve: {audit['errors'][:10]}")
    return {**record, "anchor": anchor, "record": str(destination.resolve())}


def list_feedback(output: Path, status: str = "open") -> dict[str, Any]:
    output = output.resolve()
    if status not in {"open", "resolved", "all"}:
        raise CkbError("feedback list status must be open, resolved, or all")
    prepare_feedback_store(output)
    statuses = ("open", "resolved") if status == "all" else (status,)
    rows = []
    for value in statuses:
        for path in sorted((output / "workspace-meta/feedback" / value).glob("*.json")):
            record = json_load(path)
            anchor = locate_feedback(output, str(record["id"]))["anchor"]
            rows.append(
                {
                    "id": record["id"],
                    "status": record["status"],
                    "severity": record["severity"],
                    "target": record["target"],
                    "target_title": record["target_title"],
                    "target_lines": record["target_lines"],
                    "comment": record["comment"],
                    "decision": record.get("decision"),
                    "anchor": anchor,
                    "record": str(path.resolve()),
                }
            )
    rows.sort(key=lambda item: (SEVERITY_ORDER.get(item["severity"], 99), item["target"], item["id"]))
    grouped: dict[str, list[str]] = defaultdict(list)
    for row in rows:
        grouped[row["target"]].append(row["id"])
    return {
        "schema_version": FEEDBACK_SCHEMA_VERSION,
        "status": "ready",
        "selection": status,
        "count": len(rows),
        "grouped_by_target": [{"target": key, "feedback_ids": grouped[key]} for key in sorted(grouped)],
        "feedback": rows,
    }


def audit_feedback(output: Path) -> dict[str, Any]:
    output = output.resolve()
    prepare_feedback_store(output)
    errors: list[dict[str, Any]] = []
    records = []
    seen: set[str] = set()
    seen_titles: set[str] = set()
    for directory_status in ("open", "resolved"):
        root = output / "workspace-meta/feedback" / directory_status
        for path in sorted(root.glob("*.json")):
            try:
                record = json_load(path)
            except Exception as exc:
                errors.append({"reason": "feedback-record-invalid-json", "path": str(path), "detail": str(exc)})
                continue
            feedback_id = str(record.get("id", ""))
            if feedback_id in seen:
                errors.append({"reason": "feedback-id-duplicate", "feedback_id": feedback_id})
            seen.add(feedback_id)
            if path.stem != feedback_id or not re.fullmatch(r"feedback-\d{8}-\d{6}-\d{2,}", feedback_id):
                errors.append({"reason": "feedback-id-invalid", "path": str(path), "feedback_id": feedback_id})
            if record.get("schema_version") != FEEDBACK_SCHEMA_VERSION:
                errors.append({"reason": "feedback-schema-version", "feedback_id": feedback_id})
            required = {
                "id",
                "status",
                "target",
                "target_title",
                "title",
                "target_lines",
                "anchor_before",
                "anchor_text",
                "anchor_after",
                "severity",
                "author",
                "source",
                "created_at_utc",
                "comment",
            }
            missing = sorted(required - set(record))
            line_range = record.get("target_lines")
            if missing or not isinstance(line_range, list) or len(line_range) != 2 or not all(isinstance(value, int) for value in line_range):
                errors.append({"reason": "feedback-record-shape-invalid", "feedback_id": feedback_id, "missing": missing})
                continue
            title = str(record.get("title", ""))
            if title in seen_titles:
                errors.append({"reason": "feedback-visible-title-duplicate", "feedback_id": feedback_id, "title": title})
            seen_titles.add(title)
            if record.get("status") != directory_status:
                errors.append({"reason": "feedback-status-directory-mismatch", "feedback_id": feedback_id})
            if record.get("severity") not in SEVERITIES:
                errors.append({"reason": "feedback-severity-invalid", "feedback_id": feedback_id})
            if record.get("source") not in SOURCES:
                errors.append({"reason": "feedback-source-invalid", "feedback_id": feedback_id})
            if not _contains_chinese(record.get("comment")):
                errors.append({"reason": "feedback-comment-not-chinese", "feedback_id": feedback_id})
            target_valid = True
            try:
                _canonical_relative_target(output, Path(str(record.get("target", ""))))
                location = locate_feedback(output, feedback_id)["anchor"]
            except Exception as exc:
                errors.append({"reason": "feedback-target-invalid", "feedback_id": feedback_id, "detail": str(exc)})
                target_valid = False
                location = {"status": "unavailable"}
            if directory_status == "open" and target_valid and location.get("status") == "stale":
                errors.append({"reason": "feedback-anchor-stale", "feedback_id": feedback_id})
            decision = record.get("decision")
            if directory_status == "open" and decision not in {None, "deferred"}:
                errors.append({"reason": "feedback-open-decision-invalid", "feedback_id": feedback_id})
            if directory_status == "open" and decision == "deferred" and not _contains_chinese(record.get("resolution")):
                errors.append({"reason": "feedback-deferred-resolution-not-chinese", "feedback_id": feedback_id})
            if directory_status == "resolved":
                if decision not in {"accepted", "partial", "rejected"}:
                    errors.append({"reason": "feedback-resolved-decision-invalid", "feedback_id": feedback_id})
                if not _contains_chinese(record.get("resolution")):
                    errors.append({"reason": "feedback-resolution-not-chinese", "feedback_id": feedback_id})
                if decision in {"accepted", "partial"}:
                    applied_value = record.get("applied_record")
                    try:
                        _canonical_applied_record(output, output / str(applied_value)) if applied_value else None
                        applied_valid = bool(applied_value)
                    except CkbError:
                        applied_valid = False
                    if not applied_valid:
                        errors.append({"reason": "feedback-applied-record-missing", "feedback_id": feedback_id})
            relative = _visible_relative(directory_status, feedback_id)
            mirrors = [output / root / relative for root in ("markdown", "human")]
            if not all(path_value.is_file() for path_value in mirrors):
                errors.append({"reason": "feedback-visible-mirror-missing", "feedback_id": feedback_id})
            elif mirrors[0].read_bytes() != mirrors[1].read_bytes():
                errors.append({"reason": "feedback-visible-mirror-differs", "feedback_id": feedback_id})
            else:
                text = mirrors[0].read_text(encoding="utf-8-sig")
                if text.startswith("---\n") or text.count("#类型/反馈") != 1 or LONG_HEX.search(text):
                    errors.append({"reason": "feedback-visible-shape-invalid", "feedback_id": feedback_id})
            records.append({"feedback_id": feedback_id, "status": directory_status, "anchor_status": location.get("status")})
    result = {
        "schema_version": FEEDBACK_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
        "counts": {
            "open": sum(1 for item in records if item["status"] == "open"),
            "resolved": sum(1 for item in records if item["status"] == "resolved"),
            "stale_open": sum(1 for item in records if item["status"] == "open" and item["anchor_status"] == "stale"),
        },
        "records": records,
        "errors": errors,
    }
    json_write(output / "workspace-meta/feedback-audit.json", result)
    return result


def _query_terms(question: str) -> list[str]:
    terms = {value.casefold() for value in re.findall(r"[A-Za-z0-9_.:#/-]{2,}", question)}
    for run in re.findall(r"[\u3400-\u9fff]+", question):
        terms.add(run)
        terms.update(run[index : index + 2] for index in range(max(0, len(run) - 1)))
    return sorted(terms, key=lambda value: (-len(value), value))


def search_feedback(output: Path, question: str, limit: int = 8) -> list[dict[str, Any]]:
    """Return deterministic feedback matches without mutating the knowledge base."""
    output = output.resolve()
    root = output / "workspace-meta/feedback"
    if not root.is_dir():
        return []
    terms = _query_terms(question)
    rows = []
    for status in ("open", "resolved"):
        for path in sorted((root / status).glob("*.json")):
            record = json_load(path)
            haystack = "\n".join(
                str(record.get(field) or "")
                for field in ("target", "target_title", "comment", "resolution", "severity", "decision", "status")
            ).casefold()
            matches = [term for term in terms if term in haystack]
            score = sum(8 + min(len(term), 12) for term in matches)
            if status == "open":
                score += 25
            score += max(0, 8 - 2 * SEVERITY_ORDER.get(str(record.get("severity")), 4))
            if terms and not matches and not re.search(r"反馈|纠错|audit|feedback", question, re.IGNORECASE):
                continue
            rows.append(
                {
                    "feedback_id": record["id"],
                    "title": record["title"],
                    "status": record["status"],
                    "severity": record["severity"],
                    "target": record["target"],
                    "target_title": record["target_title"],
                    "comment": record["comment"],
                    "decision": record.get("decision"),
                    "resolution": record.get("resolution"),
                    "human_file": _visible_relative(status, record["id"]).as_posix(),
                    "score": score,
                }
            )
    rows.sort(key=lambda item: (-item["score"], SEVERITY_ORDER.get(item["severity"], 99), item["target"], item["feedback_id"]))
    return rows[: max(0, limit)]

"""Deterministic Git-to-knowledge fact freshness state.

This machine-only layer observes the live repository without changing the fixed
source graph.  It records bounded drift summaries, disposable dirty overlays,
isolated migration plans, and conservative collaboration candidates.
"""

from __future__ import annotations

from contextlib import contextmanager
from datetime import datetime, timedelta, timezone
import hashlib
import json
import os
from pathlib import Path
import re
import time
from typing import Any, Iterator
import uuid

from .common import CkbError, json_load, json_write, path_inside, run, stable_id, utc_now


FRESHNESS_SCHEMA_VERSION = 1
FRESHNESS_STATES = {
    "current",
    "stale-committed",
    "provisional-dirty",
    "migration-pending",
    "migration-ready",
    "unavailable",
}
COLLABORATION_STATUSES = {"implemented", "planned", "superseded"}
MAX_CHANGED_PATHS = 100
MAX_DIRTY_PATHS = 100
MAX_EVENTS = 100
MAX_SESSION_CACHE = 64
MAX_OVERLAYS = 64
MAX_COLLABORATION_RECORDS = 1000
OVERLAY_LIFETIME_SECONDS = 24 * 60 * 60
GIT_TIMEOUT_SECONDS = 20
LOCK_TIMEOUT_SECONDS = 10.0
LOCK_STALE_SECONDS = 60.0
LOCK_RELEASE_TIMEOUT_SECONDS = 1.0
LOCK_RETRY_SECONDS = 0.025
_HEX_OBJECT = re.compile(r"[0-9a-fA-F]{7,64}")
_GIT_ACTION = re.compile(
    r"(?i)(?:^|[;&|]\s*|\s)git(?:\.exe)?"
    r"(?:\s+-C\s+(?:\"[^\"]+\"|'[^']+'|\S+)|\s+--(?:git-dir|work-tree)(?:=\S+|\s+\S+)|\s+-[^\s]+)*"
    r"\s+(commit|merge|pull|switch|checkout)\b"
)


def _root(output: Path) -> Path:
    value = output.resolve() / "workspace-meta" / "freshness"
    for relative in ("overlays", "plans"):
        (value / relative).mkdir(parents=True, exist_ok=True)
    return value


def _pid_alive(pid: Any) -> bool:
    try:
        value = int(pid)
    except (TypeError, ValueError):
        return False
    if value <= 0:
        return False
    if value == os.getpid():
        return True
    if os.name == "nt":
        import ctypes

        handle = ctypes.windll.kernel32.OpenProcess(0x1000, False, value)
        if handle:
            ctypes.windll.kernel32.CloseHandle(handle)
            return True
        return False
    try:
        os.kill(value, 0)
        return True
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    except OSError:
        return False


def _read_lock(path: Path) -> dict[str, Any]:
    try:
        value = json_load(path)
        return value if isinstance(value, dict) else {}
    except Exception:
        return {}


def _lock_file_identity(path: Path) -> tuple[int, int] | None:
    try:
        metadata = path.stat()
    except OSError:
        return None
    return int(metadata.st_dev), int(metadata.st_ino)


def _release_owned_state_lock(
    lock_path: Path,
    owner_token: str,
    acquired_identity: tuple[int, int] | None,
    timeout: float,
) -> None:
    """Release only this owner while tolerating short Windows sharing conflicts."""

    deadline = time.monotonic() + max(0.0, timeout)
    last_error = "lock-remained-busy"
    while True:
        try:
            current = json_load(lock_path)
        except FileNotFoundError:
            return
        except (OSError, ValueError, TypeError, json.JSONDecodeError) as exc:
            last_error = f"read:{type(exc).__name__}:{str(exc)[:160]}"
        else:
            current_identity = _lock_file_identity(lock_path)
            if current.get("owner_token") != owner_token:
                return
            if acquired_identity is not None and current_identity != acquired_identity:
                return
            try:
                # Reopen immediately before deletion so every retry observes
                # the latest owner instead of acting on an earlier sample.
                confirmed = json_load(lock_path)
                confirmed_identity = _lock_file_identity(lock_path)
                if confirmed.get("owner_token") != owner_token:
                    return
                if acquired_identity is not None and confirmed_identity != acquired_identity:
                    return
                lock_path.unlink()
                return
            except FileNotFoundError:
                return
            except (PermissionError, OSError) as exc:
                last_error = f"unlink:{type(exc).__name__}:{str(exc)[:160]}"
        if time.monotonic() >= deadline:
            raise CkbError(
                "fact freshness state lock release timeout: "
                f"path={lock_path}; owner_token={owner_token}; last_error={last_error}"
            )
        time.sleep(LOCK_RETRY_SECONDS)


@contextmanager
def _state_lock(
    output: Path,
    timeout: float = LOCK_TIMEOUT_SECONDS,
    release_timeout: float = LOCK_RELEASE_TIMEOUT_SECONDS,
) -> Iterator[bool]:
    root = _root(output)
    lock_path = root / "state.lock"
    owner_token = uuid.uuid4().hex
    deadline = time.monotonic() + timeout
    recovered = False
    acquired = False
    acquired_identity: tuple[int, int] | None = None
    while time.monotonic() < deadline:
        try:
            descriptor = os.open(lock_path, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
            payload = {
                "schema_version": FRESHNESS_SCHEMA_VERSION,
                "owner_token": owner_token,
                "pid": os.getpid(),
                "created_unix": time.time(),
            }
            os.write(descriptor, (json.dumps(payload, sort_keys=True) + "\n").encode("utf-8"))
            os.close(descriptor)
            acquired_identity = _lock_file_identity(lock_path)
            acquired = True
            break
        except (FileExistsError, PermissionError):
            current = _read_lock(lock_path)
            created = float(current.get("created_unix") or 0)
            has_owner = bool(current.get("owner_token")) and current.get("pid") is not None
            try:
                file_age = time.time() - lock_path.stat().st_mtime
            except FileNotFoundError:
                continue
            stale = (has_owner and not _pid_alive(current.get("pid"))) or (
                not has_owner and file_age > LOCK_STALE_SECONDS
            )
            if stale:
                try:
                    observed_identity = (
                        current.get("owner_token"),
                        current.get("pid"),
                        current.get("created_unix"),
                    )
                    latest = _read_lock(lock_path)
                    latest_identity = (
                        latest.get("owner_token"),
                        latest.get("pid"),
                        latest.get("created_unix"),
                    )
                    if observed_identity != latest_identity:
                        continue
                    lock_path.unlink()
                    recovered = True
                    continue
                except FileNotFoundError:
                    continue
                except PermissionError:
                    pass
            time.sleep(0.025)
    if not acquired:
        raise CkbError(f"fact freshness state lock timeout: {lock_path}")
    try:
        yield recovered
    finally:
        _release_owned_state_lock(lock_path, owner_token, acquired_identity, release_timeout)


def _bounded_text(value: Any, field: str, limit: int = 2000) -> str:
    text = str(value or "").strip()
    if not text or len(text) > limit or any(character in text for character in ("\x00", "\r", "\n")):
        raise CkbError(f"fact freshness {field} must be bounded nonempty single-line text")
    return text


def _repository_binding(output: Path, repository: Path | None) -> tuple[Path, dict[str, Any], str]:
    state_path = output.resolve() / "state.json"
    if not state_path.is_file():
        raise CkbError(f"fact freshness requires knowledge state.json: {state_path}")
    state = json_load(state_path)
    if not isinstance(state, dict) or state.get("status") != "complete":
        raise CkbError("fact freshness requires a complete knowledge output state")
    binding = state.get("repository")
    if not isinstance(binding, dict):
        raise CkbError("fact freshness knowledge state has no repository binding")
    bound_commit = str(binding.get("commit") or "").strip()
    if not _HEX_OBJECT.fullmatch(bound_commit):
        raise CkbError("fact freshness knowledge state has no valid bound commit")
    configured_root = str(binding.get("root") or "").strip()
    repo = (repository or (Path(configured_root) if configured_root else None))
    if repo is None:
        raise CkbError("fact freshness repository root is unavailable")
    repo = repo.expanduser().resolve()
    if not repo.is_dir():
        raise CkbError(f"fact freshness repository root is missing: {repo}")
    return repo, state, bound_commit


def _git(repo: Path, *arguments: str, allow_failure: bool = False) -> str | None:
    completed = run(["git", "-C", str(repo), *arguments], timeout=GIT_TIMEOUT_SECONDS)
    if completed.returncode:
        if allow_failure:
            return None
        detail = (completed.stderr or completed.stdout).strip()
        raise CkbError(f"fact freshness Git probe failed: git -C {repo} {' '.join(arguments)}: {detail[:500]}")
    return completed.stdout.strip()


def _status_records(repo: Path) -> list[dict[str, str]]:
    completed = run(
        ["git", "-C", str(repo), "status", "--porcelain=v1", "-z", "--untracked-files=all"],
        timeout=GIT_TIMEOUT_SECONDS,
    )
    if completed.returncode:
        detail = (completed.stderr or completed.stdout).strip()
        raise CkbError(f"fact freshness Git status failed: {detail[:500]}")
    frames = completed.stdout.split("\0")
    records: list[dict[str, str]] = []
    index = 0
    while index < len(frames):
        frame = frames[index]
        index += 1
        if len(frame) < 3:
            continue
        status = frame[:2]
        path = frame[3:].replace("\\", "/")
        if path:
            records.append({"status": status, "path": path})
        if any(marker in status for marker in ("R", "C")) and index < len(frames):
            index += 1
    return sorted(records, key=lambda item: (item["path"], item["status"]))


def _repository_snapshot(repo: Path) -> dict[str, Any]:
    top = _git(repo, "rev-parse", "--show-toplevel")
    if not top or Path(top).resolve() != repo.resolve():
        raise CkbError(f"fact freshness repository must be the Git worktree root: {repo}")
    head = _git(repo, "rev-parse", "--verify", "HEAD")
    tree = _git(repo, "rev-parse", "HEAD^{tree}")
    branch = _git(repo, "symbolic-ref", "--quiet", "--short", "HEAD", allow_failure=True)
    dirty_records = _status_records(repo)
    signature_payload = {
        "head": head,
        "tree": tree,
        "branch": branch,
        "dirty": dirty_records,
    }
    signature = hashlib.sha256(
        json.dumps(signature_payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()
    return {
        **signature_payload,
        "signature": signature,
        "dirty_paths": [item["path"] for item in dirty_records[:MAX_DIRTY_PATHS]],
        "dirty_count": len(dirty_records),
        "dirty_truncated": len(dirty_records) > MAX_DIRTY_PATHS,
    }


def _change_summary(repo: Path, bound_commit: str, current_head: str) -> dict[str, Any]:
    if bound_commit == current_head:
        return {
            "comparison": "bound-commit-to-current-head",
            "changed": 0,
            "changed_paths": [],
            "counts": {},
            "truncated": False,
        }
    if _git(repo, "cat-file", "-e", f"{bound_commit}^{{commit}}", allow_failure=True) is None:
        raise CkbError(f"fact freshness bound commit object is unavailable: {bound_commit}")
    completed = run(
        ["git", "-C", str(repo), "diff", "--name-status", "--find-renames", bound_commit, current_head],
        timeout=GIT_TIMEOUT_SECONDS,
    )
    if completed.returncode:
        detail = (completed.stderr or completed.stdout).strip()
        raise CkbError(f"fact freshness committed range diff failed: {detail[:500]}")
    changes: list[dict[str, Any]] = []
    counts: dict[str, int] = {}
    for line in completed.stdout.splitlines():
        fields = line.split("\t")
        if len(fields) < 2:
            continue
        raw_status = fields[0]
        kind = raw_status[:1] or "?"
        counts[kind] = counts.get(kind, 0) + 1
        changes.append(
            {
                "status": raw_status,
                "path": fields[-1].replace("\\", "/"),
                **({"from_path": fields[1].replace("\\", "/")} if len(fields) > 2 else {}),
            }
        )
    return {
        "comparison": "bound-commit-to-current-head",
        "changed": len(changes),
        "changed_paths": [item["path"] for item in changes[:MAX_CHANGED_PATHS]],
        "changes": changes[:MAX_CHANGED_PATHS],
        "counts": dict(sorted(counts.items())),
        "truncated": len(changes) > MAX_CHANGED_PATHS,
    }


def _iso_after(seconds: int) -> str:
    return (datetime.now(timezone.utc) + timedelta(seconds=seconds)).strftime("%Y-%m-%dT%H:%M:%SZ")


def _prune_overlays(root: Path) -> None:
    paths = sorted((root / "overlays").glob("*.json"), key=lambda item: item.stat().st_mtime, reverse=True)
    now = time.time()
    for index, path in enumerate(paths):
        try:
            record = json_load(path)
            expired = float(record.get("lifetime", {}).get("expires_unix") or 0) <= now
        except Exception:
            expired = True
        if expired or index >= MAX_OVERLAYS:
            path.unlink(missing_ok=True)


def _write_overlay(
    output: Path,
    repository: Path,
    snapshot: dict[str, Any],
    session_id: str,
    trigger: str,
) -> dict[str, Any]:
    root = _root(output)
    overlay_id = stable_id("freshness-overlay", str(output.resolve()), session_id, snapshot["head"], snapshot["signature"])
    path = root / "overlays" / f"{overlay_id}.json"
    created_unix = time.time()
    record = {
        "schema_version": FRESHNESS_SCHEMA_VERSION,
        "overlay_id": overlay_id,
        "status": "provisional-dirty",
        "write_layer": "machine-temporary-overlay",
        "repository": str(repository.resolve()),
        "head": snapshot["head"],
        "worktree_signature": snapshot["signature"],
        "dirty_paths": snapshot["dirty_paths"],
        "dirty_count": snapshot["dirty_count"],
        "dirty_truncated": snapshot["dirty_truncated"],
        "source": {"session_id": session_id, "trigger": trigger},
        "lifetime": {
            "policy": "discardable-24h",
            "created_at_utc": utc_now(),
            "expires_at_utc": _iso_after(OVERLAY_LIFETIME_SECONDS),
            "expires_unix": created_unix + OVERLAY_LIFETIME_SECONDS,
        },
        "discard": {
            "action": "delete-machine-overlay-only",
            "command": ["freshness", "overlay-discard", "--out", str(output.resolve()), "--overlay-id", overlay_id],
            "git_worktree_changed": False,
        },
        "promoted_to_stable_facts": False,
        "promoted_to_human_layer": False,
    }
    json_write(path, record)
    _prune_overlays(root)
    return {**record, "path": str(path.resolve())}


def _migration_evidence(plan: dict[str, Any], current_head: str) -> dict[str, Any]:
    staging = Path(str(plan.get("staging_output") or "")).expanduser().resolve()
    blockers: list[str] = []
    staging_state: dict[str, Any] = {}
    if not staging.is_dir():
        blockers.append("staging-output-missing")
    else:
        state_path = staging / "state.json"
        if not state_path.is_file():
            blockers.append("staging-state-missing")
        else:
            try:
                staging_state = json_load(state_path)
            except Exception:
                blockers.append("staging-state-invalid")
        if staging_state.get("status") != "complete":
            blockers.append("staging-not-complete")
        staging_commit = str((staging_state.get("repository") or {}).get("commit") or "")
        if staging_commit != current_head:
            blockers.append("staging-target-commit-mismatch")
        if not (staging / ".complete").is_file():
            blockers.append("staging-complete-marker-missing")
        for relative, reason in (
            ("audit/global.json", "staging-global-audit-not-passed"),
            ("migration/audit.json", "staging-migration-audit-not-passed"),
        ):
            path = staging / relative
            try:
                passed = path.is_file() and json_load(path).get("status") == "passed"
            except Exception:
                passed = False
            if not passed:
                blockers.append(reason)
    return {
        **plan,
        "status": "ready" if not blockers else "pending",
        "target_commit": current_head,
        "staging_output": str(staging),
        "blockers": blockers,
        "cutover_performed": False,
    }


def _next_action(state: str, output: Path, repository: Path | None, head: str | None, overlay: dict[str, Any] | None, migration: dict[str, Any] | None) -> dict[str, Any]:
    if state == "current":
        return {"action": "reuse-stable-facts", "rebuild": False}
    if state == "stale-committed":
        staging = output.resolve().parent / f"{output.resolve().name}.staging-{str(head or 'unknown')[:12]}"
        return {
            "action": "create-migration-plan",
            "staging_output": str(staging),
            "command": [
                "freshness",
                "plan",
                "--out",
                str(output.resolve()),
                "--repo",
                str(repository.resolve()) if repository else "REPOSITORY",
                "--staging-out",
                str(staging),
            ],
        }
    if state == "provisional-dirty":
        return {
            "action": "commit-or-discard-worktree-overlay",
            "overlay_id": overlay.get("overlay_id") if overlay else None,
            "overlay_discard": overlay.get("discard", {}).get("command") if overlay else None,
            "git_worktree_changed_by_discard": False,
        }
    if state == "migration-pending":
        return {
            "action": "complete-isolated-staging",
            "staging_output": migration.get("staging_output") if migration else None,
            "blockers": migration.get("blockers", []) if migration else [],
        }
    if state == "migration-ready":
        return {
            "action": "review-and-cutover-explicitly",
            "staging_output": migration.get("staging_output") if migration else None,
            "automatic_cutover": False,
        }
    return {"action": "retry-freshness-check", "automatic_assumption": False}


def _event_record(result: dict[str, Any], trigger: str) -> dict[str, Any]:
    return {
        "schema_version": FRESHNESS_SCHEMA_VERSION,
        "event_id": stable_id(
            "freshness-event",
            trigger,
            result.get("current_head"),
            result.get("worktree_signature"),
            time.time_ns(),
        ),
        "observed_at_utc": result["observed_at_utc"],
        "trigger": trigger,
        "state": result["state"],
        "stable_state": result.get("stable_state"),
        "current_head": result.get("current_head"),
        "branch": result.get("branch"),
        "dirty_count": result.get("dirty", {}).get("count"),
        "error": result.get("error"),
    }


def _write_events(root: Path, events: list[dict[str, Any]]) -> None:
    path = root / "events.jsonl"
    temporary = path.with_suffix(".tmp")
    temporary.write_text(
        "".join(json.dumps(item, ensure_ascii=False, sort_keys=True) + "\n" for item in events[-MAX_EVENTS:]),
        encoding="utf-8",
        newline="\n",
    )
    os.replace(temporary, path)


def _last_confirmed(previous: dict[str, Any]) -> dict[str, Any] | None:
    stored = previous.get("last_confirmed")
    if isinstance(stored, dict):
        return stored
    if previous.get("state") in FRESHNESS_STATES - {"unavailable"}:
        return {
            key: previous.get(key)
            for key in ("state", "stable_state", "bound_commit", "current_head", "branch", "observed_at_utc")
        }
    return None


def _unavailable_result(output: Path, trigger: str, previous: dict[str, Any], error: Exception, recovered: bool) -> dict[str, Any]:
    result = {
        "schema_version": FRESHNESS_SCHEMA_VERSION,
        "state": "unavailable",
        "stable_state": "unavailable",
        "observed_at_utc": utc_now(),
        "trigger": trigger,
        "bound_commit": None,
        "current_head": None,
        "branch": None,
        "dirty": {"count": None, "paths": [], "truncated": False},
        "change_summary": None,
        "migration": None,
        "overlay": None,
        "cache_hit": False,
        "lock_recovered": recovered,
        "recovered_from_unavailable": False,
        "stable_facts_current": False,
        "last_confirmed": _last_confirmed(previous),
        "error": {"type": type(error).__name__, "message": str(error)[:500]},
        "writes": {"machine_freshness": True, "stable_facts": False, "human_layer": False},
        "next_action": _next_action("unavailable", output, None, None, None, None),
        "session_cache": dict(previous.get("session_cache") or {}),
    }
    return result


def check_fact_freshness(
    output: Path,
    repository: Path | None = None,
    *,
    session_id: str | None = None,
    trigger: str = "explicit-status",
    force: bool = False,
) -> dict[str, Any]:
    """Inspect one live repository and atomically update only machine freshness state."""

    output = output.expanduser().resolve()
    session = str(session_id or os.environ.get("CKB_FRESHNESS_SESSION_ID") or f"process-{os.getpid()}").strip()
    trigger_value = _bounded_text(trigger, "trigger", 200)
    probe: tuple[Path, dict[str, Any], str, dict[str, Any]] | None = None
    probe_error: Exception | None = None
    try:
        repo, knowledge_state, bound_commit = _repository_binding(output, repository)
        snapshot = _repository_snapshot(repo)
        probe = (repo, knowledge_state, bound_commit, snapshot)
    except Exception as exc:
        probe_error = exc
    with _state_lock(output) as lock_recovered:
        root = _root(output)
        state_path = root / "state.json"
        try:
            previous = json_load(state_path) if state_path.is_file() else {}
            if not isinstance(previous, dict):
                previous = {}
        except Exception:
            previous = {}
        try:
            if probe_error is not None:
                raise probe_error
            assert probe is not None
            repo, knowledge_state, bound_commit, snapshot = probe
            cache = dict(previous.get("session_cache") or {})
            cache_entry = cache.get(session) if isinstance(cache.get(session), dict) else None
            cache_hit = bool(cache_entry and cache_entry.get("signature") == snapshot["signature"] and not force)
            if cache_hit and isinstance(cache_entry.get("change_summary"), dict):
                change_summary = cache_entry["change_summary"]
            else:
                change_summary = _change_summary(repo, bound_commit, snapshot["head"])
            stable_state = "current" if snapshot["head"] == bound_commit else "stale-committed"
            migration = None
            plan = previous.get("migration_plan")
            if stable_state == "stale-committed" and isinstance(plan, dict):
                if plan.get("bound_commit") == bound_commit and plan.get("target_commit") == snapshot["head"]:
                    migration = _migration_evidence(plan, snapshot["head"])
                    stable_state = "migration-ready" if migration["status"] == "ready" else "migration-pending"
            overlay = None
            outward_state = stable_state
            if snapshot["dirty_count"]:
                overlay = _write_overlay(output, repo, snapshot, session, trigger_value)
                outward_state = "provisional-dirty"
            observed = utc_now()
            previous_unavailable = previous.get("state") == "unavailable"
            result = {
                "schema_version": FRESHNESS_SCHEMA_VERSION,
                "state": outward_state,
                "stable_state": stable_state,
                "observed_at_utc": observed,
                "trigger": trigger_value,
                "repository": str(repo),
                "knowledge_state": str((output / "state.json").resolve()),
                "knowledge_state_status": knowledge_state.get("status"),
                "bound_commit": bound_commit,
                "current_head": snapshot["head"],
                "current_tree": snapshot["tree"],
                "branch": snapshot["branch"],
                "worktree_signature": snapshot["signature"],
                "dirty": {
                    "count": snapshot["dirty_count"],
                    "paths": snapshot["dirty_paths"],
                    "truncated": snapshot["dirty_truncated"],
                },
                "change_summary": change_summary,
                "migration": migration,
                "migration_plan": plan if isinstance(plan, dict) else None,
                "overlay": overlay,
                "cache_hit": cache_hit,
                "forced": force,
                "lock_recovered": lock_recovered,
                "recovered_from_unavailable": previous_unavailable,
                "stable_facts_current": outward_state == "current",
                "last_confirmed": {
                    "state": outward_state,
                    "stable_state": stable_state,
                    "bound_commit": bound_commit,
                    "current_head": snapshot["head"],
                    "branch": snapshot["branch"],
                    "observed_at_utc": observed,
                },
                "error": None,
                "writes": {"machine_freshness": True, "stable_facts": False, "human_layer": False},
            }
            result["next_action"] = _next_action(outward_state, output, repo, snapshot["head"], overlay, migration)
            cache[session] = {
                "signature": snapshot["signature"],
                "head": snapshot["head"],
                "change_summary": change_summary,
                "stable_state": stable_state,
                "observed_at_utc": observed,
            }
            cache_items = sorted(cache.items(), key=lambda item: str(item[1].get("observed_at_utc") or ""), reverse=True)
            result["session_cache"] = dict(cache_items[:MAX_SESSION_CACHE])
        except Exception as exc:
            result = _unavailable_result(output, trigger_value, previous, exc, lock_recovered)
        previous_events = list(previous.get("recent_events") or []) if isinstance(previous.get("recent_events"), list) else []
        event = _event_record(result, trigger_value)
        recent_events = [*previous_events, event][-MAX_EVENTS:]
        result["recent_events"] = recent_events
        json_write(state_path, result)
        _write_events(root, recent_events)
        public = dict(result)
        public["state_file"] = str(state_path.resolve())
        public.pop("session_cache", None)
        return public


def create_migration_plan(
    output: Path,
    repository: Path,
    staging_output: Path,
    *,
    session_id: str | None = None,
) -> dict[str, Any]:
    output = output.expanduser().resolve()
    repository = repository.expanduser().resolve()
    staging = staging_output.expanduser().resolve()
    if staging == output or path_inside(staging, output) or path_inside(output, staging):
        raise CkbError("fact freshness staging output must be isolated from the stable output")
    if staging == repository or path_inside(staging, repository):
        raise CkbError("fact freshness staging output must not overlap the source repository")
    observed = check_fact_freshness(output, repository, session_id=session_id, trigger="migration-plan-preflight", force=True)
    if observed["stable_state"] not in {"stale-committed", "migration-pending", "migration-ready"}:
        raise CkbError(f"fact freshness migration plan requires committed HEAD drift: state={observed['state']}")
    plan_id = stable_id("freshness-migration", str(output), observed["bound_commit"], observed["current_head"], str(staging))
    plan = {
        "schema_version": FRESHNESS_SCHEMA_VERSION,
        "plan_id": plan_id,
        "status": "pending",
        "stable_output": str(output),
        "repository": str(repository),
        "bound_commit": observed["bound_commit"],
        "target_commit": observed["current_head"],
        "staging_output": str(staging),
        "created_at_utc": utc_now(),
        "created_by_session": str(session_id or "unspecified"),
        "command": [
            "migrate",
            "start",
            "--from-out",
            str(output),
            "--repo",
            str(repository),
            "--out",
            str(staging),
        ],
        "automatic_cutover": False,
        "stable_output_overwritten": False,
    }
    with _state_lock(output):
        root = _root(output)
        state_path = root / "state.json"
        current = json_load(state_path)
        if current.get("current_head") != plan["target_commit"] or current.get("bound_commit") != plan["bound_commit"]:
            raise CkbError("fact freshness repository changed while creating the migration plan")
        json_write(root / "plans" / f"{plan_id}.json", plan)
        current["migration_plan"] = plan
        current["migration"] = {**plan, "blockers": ["staging-output-missing"]}
        current["stable_state"] = "migration-pending"
        if current.get("state") != "provisional-dirty":
            current["state"] = "migration-pending"
        current["stable_facts_current"] = False
        current["next_action"] = _next_action(current["state"], output, repository, plan["target_commit"], current.get("overlay"), current["migration"])
        json_write(state_path, current)
    return {
        **plan,
        "state": "provisional-dirty" if observed["state"] == "provisional-dirty" else "migration-pending",
        "stable_state": "migration-pending",
        "plan_path": str((_root(output) / "plans" / f"{plan_id}.json").resolve()),
        "writes": {"machine_freshness": True, "stable_facts": False, "human_layer": False},
    }


def discard_overlay(output: Path, overlay_id: str) -> dict[str, Any]:
    output = output.expanduser().resolve()
    identity = _bounded_text(overlay_id, "overlay_id", 200)
    if not re.fullmatch(r"freshness-overlay-[0-9a-f]{32}", identity):
        raise CkbError("fact freshness overlay_id has invalid shape")
    with _state_lock(output):
        path = _root(output) / "overlays" / f"{identity}.json"
        existed = path.is_file()
        path.unlink(missing_ok=True)
        state_path = _root(output) / "state.json"
        if state_path.is_file():
            state = json_load(state_path)
            if (state.get("overlay") or {}).get("overlay_id") == identity:
                state["overlay"] = None
                json_write(state_path, state)
    return {
        "schema_version": FRESHNESS_SCHEMA_VERSION,
        "status": "discarded" if existed else "not-found",
        "overlay_id": identity,
        "machine_overlay_deleted": existed,
        "git_worktree_changed": False,
        "stable_facts_changed": False,
        "human_layer_changed": False,
    }


def _command_strings(value: Any) -> Iterator[str]:
    if isinstance(value, dict):
        preferred = {"command", "cmd", "script", "shell_command", "shellcommand", "input"}
        for key, child in value.items():
            if str(key).casefold() in preferred and isinstance(child, str):
                yield child
            elif isinstance(child, (dict, list)):
                yield from _command_strings(child)
    elif isinstance(value, list):
        for child in value:
            yield from _command_strings(child)
    elif isinstance(value, str):
        yield value


def classify_git_trigger(tool_input: Any) -> str | None:
    """Classify only successful Git actions that can change HEAD or branch."""

    for command in _command_strings(tool_input):
        match = _GIT_ACTION.search(command.strip())
        if not match:
            continue
        action = match.group(1).casefold()
        return "branch-switch" if action in {"switch", "checkout"} else action
    return None


def _collaboration_path(output: Path) -> Path:
    return _root(output) / "collaboration.jsonl"


def _read_collaboration(output: Path) -> list[dict[str, Any]]:
    path = _collaboration_path(output)
    if not path.is_file():
        return []
    records = []
    for line in path.read_text(encoding="utf-8-sig").splitlines():
        if not line.strip():
            continue
        value = json.loads(line)
        if isinstance(value, dict):
            records.append(value)
    return records[-MAX_COLLABORATION_RECORDS:]


def _write_collaboration(output: Path, records: list[dict[str, Any]]) -> None:
    path = _collaboration_path(output)
    temporary = path.with_suffix(".tmp")
    temporary.write_text(
        "".join(json.dumps(item, ensure_ascii=False, sort_keys=True) + "\n" for item in records[-MAX_COLLABORATION_RECORDS:]),
        encoding="utf-8",
        newline="\n",
    )
    os.replace(temporary, path)


def _relative_paths(paths: list[str] | None) -> list[str]:
    result = []
    for raw in paths or []:
        value = _bounded_text(raw, "collaboration path", 1000).replace("\\", "/").strip("/")
        if not value or value == "." or value.startswith("../") or "/../" in f"/{value}/":
            raise CkbError(f"fact freshness collaboration path must be relative: {raw}")
        result.append(value)
    return sorted(set(result))[:100]


def record_collaboration(
    output: Path,
    *,
    feature: str,
    summary: str,
    status: str,
    branch: str,
    commit: str,
    task: str,
    paths: list[str] | None = None,
    supersedes: list[str] | None = None,
) -> dict[str, Any]:
    output = output.expanduser().resolve()
    status_value = str(status or "").strip().casefold()
    if status_value not in COLLABORATION_STATUSES:
        raise CkbError(f"fact freshness collaboration status must be one of {sorted(COLLABORATION_STATUSES)}")
    feature_value = _bounded_text(feature, "feature", 500)
    summary_value = _bounded_text(summary, "summary", 2000)
    branch_value = _bounded_text(branch, "branch", 500)
    commit_value = _bounded_text(commit, "commit", 64)
    if not _HEX_OBJECT.fullmatch(commit_value):
        raise CkbError("fact freshness collaboration commit must be a Git object id")
    task_value = _bounded_text(task, "task", 500)
    path_values = _relative_paths(paths)
    supersedes_values = sorted(set(_bounded_text(item, "supersedes record", 200) for item in (supersedes or [])))[:100]
    record_id = stable_id(
        "freshness-collaboration",
        feature_value,
        summary_value,
        status_value,
        branch_value,
        commit_value,
        task_value,
        json.dumps(path_values),
        json.dumps(supersedes_values),
    )
    record = {
        "schema_version": FRESHNESS_SCHEMA_VERSION,
        "record_id": record_id,
        "feature": feature_value,
        "summary": summary_value,
        "status": status_value,
        "branch": branch_value,
        "commit": commit_value,
        "task": task_value,
        "paths": path_values,
        "supersedes": supersedes_values,
        "recorded_at_utc": utc_now(),
        "write_layer": "machine-collaboration",
        "automatic_duplicate_decision": False,
    }
    with _state_lock(output):
        records = _read_collaboration(output)
        existing = next((item for item in records if item.get("record_id") == record_id), None)
        if existing is not None:
            return {**existing, "idempotent": True}
        records.append(record)
        _write_collaboration(output, records)
    return {**record, "idempotent": False}


def _feature_terms(text: str) -> set[str]:
    values = re.findall(r"[A-Za-z0-9_.-]{2,}|[\u3400-\u9fff]{2,}", text.casefold())
    terms: set[str] = set()
    for value in values:
        terms.add(value)
        if re.fullmatch(r"[\u3400-\u9fff]+", value) and len(value) > 2:
            terms.update(value[index : index + 2] for index in range(len(value) - 1))
    return terms


def query_collaboration_records(
    output: Path,
    *,
    branch: str | None = None,
    commit: str | None = None,
    task: str | None = None,
    status: str | None = None,
    summary: str | None = None,
    paths: list[str] | None = None,
    limit: int = 100,
) -> dict[str, Any]:
    output = output.expanduser().resolve()
    if limit < 1 or limit > 500:
        raise CkbError("fact freshness collaboration query limit must be in [1, 500]")
    records = _read_collaboration(output)
    filters = {"branch": branch, "commit": commit, "task": task, "status": status}
    selected = records
    for field, expected in filters.items():
        if expected is not None:
            selected = [item for item in selected if str(item.get(field) or "").casefold() == str(expected).strip().casefold()]
    selected = list(reversed(selected))[:limit]
    requested_paths = set(_relative_paths(paths))
    requested_terms = _feature_terms(str(summary or ""))
    candidates: list[dict[str, Any]] = []
    if requested_paths or requested_terms:
        for record in reversed(records):
            record_paths = set(record.get("paths") or [])
            path_overlap = sorted(requested_paths & record_paths)
            record_terms = _feature_terms(f"{record.get('feature', '')} {record.get('summary', '')}")
            union = requested_terms | record_terms
            term_overlap = sorted(requested_terms & record_terms)
            jaccard = len(term_overlap) / len(union) if union else 0.0
            if not path_overlap and jaccard < 0.35:
                continue
            reasons = []
            if path_overlap:
                reasons.append("owned-path-overlap")
            if jaccard >= 0.35:
                reasons.append("feature-term-overlap")
            candidates.append(
                {
                    "record_id": record["record_id"],
                    "classification": "candidate-only",
                    "branch": record["branch"],
                    "commit": record["commit"],
                    "task": record["task"],
                    "status": record["status"],
                    "path_overlap": path_overlap,
                    "term_overlap": term_overlap[:20],
                    "term_jaccard": round(jaccard, 6),
                    "reasons": reasons,
                    "automatic_duplicate_decision": False,
                }
            )
            if len(candidates) >= limit:
                break
    return {
        "schema_version": FRESHNESS_SCHEMA_VERSION,
        "status": "ready",
        "records": selected,
        "record_count": len(selected),
        "duplicate_candidates": candidates,
        "candidate_boundary": "candidate-only-not-a-duplicate-decision",
    }


def attach_freshness_to_retrieval(output: Path, retrieval: dict[str, Any], freshness: dict[str, Any]) -> dict[str, Any]:
    """Attach currentness evidence and prepend a compact machine-pack guard."""

    result = dict(retrieval)
    public_freshness = {
        key: freshness.get(key)
        for key in (
            "schema_version",
            "state",
            "stable_state",
            "observed_at_utc",
            "trigger",
            "bound_commit",
            "current_head",
            "branch",
            "dirty",
            "change_summary",
            "migration",
            "overlay",
            "cache_hit",
            "stable_facts_current",
            "next_action",
            "error",
            "state_file",
        )
    }
    result["fact_freshness"] = public_freshness
    result["current_source_grounded"] = bool(result.get("source_grounded")) and freshness.get("state") == "current"
    pack_value = result.get("pack")
    if isinstance(pack_value, str) and Path(pack_value).is_file():
        pack_path = Path(pack_value)
        existing = pack_path.read_text(encoding="utf-8-sig")
        state = freshness.get("state")
        if state == "current":
            guard = (
                "# 源码事实新鲜度\n\n"
                "状态：`current`。当前仓库与固定事实绑定提交一致，可复用本阅读包中的稳定事实。\n\n"
            )
        else:
            guard = (
                "# 源码事实新鲜度\n\n"
                f"状态：`{state}`；稳定层状态：`{freshness.get('stable_state')}`。"
                "本阅读包中的固定源码事实只可作为已绑定提交的历史基线；在完成当前源码核验或显式切换已通过门的 staging 前，不得据此形成当前确定性结论。\n\n"
            )
        if not existing.startswith("# 源码事实新鲜度"):
            pack_path.write_text(guard + existing, encoding="utf-8", newline="\n")
        record_value = result.get("record")
        if isinstance(record_value, str) and Path(record_value).is_file():
            record = json_load(Path(record_value))
            if isinstance(record, dict):
                record["fact_freshness"] = public_freshness
                record["current_source_grounded"] = result["current_source_grounded"]
                json_write(Path(record_value), record)
    return result

"""Graphify-compatible graph, community, report, and scoped-query projection.

The source-audited CKB graph remains the sole fact authority. This module adopts
Graphify's staged graph model and invokes its pinned deterministic community
detector after every successful Agent-reviewed merge. It deliberately does not
replace Git blob/range provenance or the CKB completion gates with fuzzy labels.
"""

from __future__ import annotations

from collections import Counter, defaultdict, deque
import hashlib
import json
import math
from pathlib import Path
import re
import sys
from typing import Any, Iterable

from .common import CkbError, json_load, json_write, sha256_file, utc_now


GRAPHIFY_UPSTREAM = "https://github.com/Graphify-Labs/graphify"
GRAPHIFY_COMMIT = "b2cd36267456c166788c95be6e68574064a92a42"
GRAPHIFY_VERSION = "0.9.48"
GRAPHIFY_PIPELINE = ["detect", "extract", "build", "cluster", "report", "export"]
GRAPHIFY_CONFIDENCE = {"EXTRACTED", "INFERRED", "AMBIGUOUS"}
GRAPHIFY_PROJECTION_SCHEMA = 1
REPORT_COMMUNITY_LIMIT = 30
REPORT_MEMBER_LIMIT = 12
QUERY_DEFAULT_BUDGET = 1500
HUMAN_REPORT_KINDS = {"class", "struct", "interface", "record", "function", "method", "constructor", "destructor"}


def _networkx_modules():
    vendor = Path(__file__).resolve().parents[1] / "_vendor"
    if str(vendor) not in sys.path:
        sys.path.insert(0, str(vendor))
    import networkx as nx  # type: ignore
    from _vendor.graphify_vendor.cluster import (  # type: ignore
        cluster,
        label_communities_by_hub,
        score_all,
    )

    return nx, cluster, label_communities_by_hub, score_all


def _canonical_json_sha256(value: Any) -> str:
    raw = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(raw).hexdigest()


def _source_location(entity: dict[str, Any]) -> str:
    source_range = entity.get("range", {})
    start = int(source_range.get("start_line", 0) or 0)
    end = int(source_range.get("end_line", start) or start)
    return f"L{start}" if start == end else f"L{start}-L{end}"


def _node_label(entity: dict[str, Any]) -> str:
    if entity.get("kind") == "file":
        return str(entity.get("path", entity["id"]))
    return str(entity.get("qualified_name") or entity.get("name") or entity["id"])


def _description(entity: dict[str, Any]) -> str:
    return str(
        entity.get("meaning_zh")
        or entity.get("description_zh")
        or entity.get("role_zh")
        or ""
    )


def _confidence(link: dict[str, Any]) -> tuple[str, float, str]:
    """Map CKB provider evidence into Graphify's three deterministic tiers."""
    provider = str(link.get("provider", ""))
    relation = str(link.get("type", "references"))
    lowered = provider.lower()
    if "lexical-candidate" in lowered:
        return "INFERRED", 0.85, "deterministic lexical target resolution"
    if "ambiguous" in lowered or relation in {"possible-reference", "possible-call"}:
        return "AMBIGUOUS", 0.55, "provider marked the target ambiguous"
    return "EXTRACTED", 1.0, "AST/LSP or source-structural evidence"


def _graphify_node(entity: dict[str, Any]) -> dict[str, Any]:
    source_range = entity.get("range", {})
    return {
        "id": entity["id"],
        "label": _node_label(entity),
        "file_type": "code",
        "node_type": entity.get("kind"),
        "language": entity.get("language"),
        "source_file": entity.get("path"),
        "source_location": _source_location(entity),
        "source_range": {
            "start_byte": source_range.get("start_byte"),
            "end_byte": source_range.get("end_byte"),
            "start_line": source_range.get("start_line"),
            "end_line": source_range.get("end_line"),
        },
        "qualified_name": entity.get("qualified_name"),
        "classification": entity.get("classification"),
        "owner_page_id": entity.get("owner_page_id"),
        "description_zh": _description(entity),
        "meaning_zh": entity.get("meaning_zh"),
        "role_zh": entity.get("role_zh"),
        "change_when_zh": entity.get("change_when_zh"),
        "review_status": entity.get("review_status"),
        "commit": entity.get("commit"),
        "blob": entity.get("blob"),
        "chunk_id": entity.get("chunk_id"),
        "scope_classification": entity.get("classification"),
    }


def _graphify_link(link: dict[str, Any], entity_by_id: dict[str, dict[str, Any]]) -> dict[str, Any]:
    confidence, score, reason = _confidence(link)
    source_entity = entity_by_id[link["source"]]
    return {
        "id": link["id"],
        "source": link["source"],
        "target": link["target"],
        "relation": link.get("type", "references"),
        "confidence": confidence,
        "confidence_score": score,
        "confidence_reason": reason,
        "source_file": link.get("evidence", {}).get("source_path") or source_entity.get("path"),
        "provider": link.get("provider"),
        "evidence": link.get("evidence", {}),
        "cross_chunk": bool(link.get("cross_chunk")),
    }


def _build_networkx(nodes: list[dict[str, Any]], links: list[dict[str, Any]]):
    nx, _cluster, _labels, _scores = _networkx_modules()
    graph = nx.MultiDiGraph()
    for node in nodes:
        attrs = {key: value for key, value in node.items() if key != "id"}
        graph.add_node(node["id"], **attrs)
    for link in links:
        attrs = {key: value for key, value in link.items() if key not in {"source", "target"}}
        graph.add_edge(link["source"], link["target"], key=link["id"], **attrs)
    return graph


def _community_records(graph, communities: dict[int, list[str]], labels: dict[int, str], scores: dict[int, float]) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    for community_id in sorted(communities):
        members = sorted(communities[community_id])
        hubs = sorted(members, key=lambda value: (-graph.degree(value), value))[:REPORT_MEMBER_LIMIT]
        records.append(
            {
                "id": community_id,
                "label": labels[community_id],
                "members": members,
                "member_count": len(members),
                "cohesion": scores[community_id],
                "hub_ids": hubs,
                "membership_sha256": _canonical_json_sha256(members),
            }
        )
    return records


def _report(
    canonical: dict[str, Any],
    nodes: list[dict[str, Any]],
    links: list[dict[str, Any]],
    communities: list[dict[str, Any]],
    graph,
) -> str:
    by_id = {node["id"]: node for node in nodes}
    readable_nodes = [
        node
        for node in nodes
        if node.get("node_type") in HUMAN_REPORT_KINDS and str(node.get("description_zh") or "").strip()
    ]
    hub_candidates = sorted(
        readable_nodes,
        key=lambda node: (0 if node.get("classification") == "page" else 1, -graph.degree(node["id"]), node["label"], node["id"]),
    )
    hubs: list[dict[str, Any]] = []
    hub_labels: set[str] = set()
    for node in hub_candidates:
        if node["label"] in hub_labels:
            continue
        hub_labels.add(node["label"])
        hubs.append(node)
        if len(hubs) == 12:
            break
    lines = [
        "# 项目关系导览",
        "",
        "> 这份导览把经常一起工作的类和函数聚成职责群，帮助人先理解结构，再进入具体实现。",
        "",
        "## 建议先看的代码",
        "",
    ]
    for node in hubs:
        description = str(node.get("description_zh") or "").strip()
        lines.append(f"- **{node['label']}**：{description}")
    if not hubs:
        lines.append("- 从项目代码导览开始，沿自然双链进入相关职责。")
    lines.extend(["", "## 按职责群浏览", ""])
    for community in communities[:REPORT_COMMUNITY_LIMIT]:
        member_candidates = sorted(
            [value for value in community["members"] if by_id[value].get("node_type") in HUMAN_REPORT_KINDS],
            key=lambda value: (
                0 if by_id[value].get("classification") == "page" else 1,
                0 if str(by_id[value].get("description_zh") or "").strip() else 1,
                -graph.degree(value),
                by_id[value]["label"],
                value,
            ),
        )
        member_ids: list[str] = []
        member_labels: set[str] = set()
        for value in member_candidates:
            if by_id[value]["label"] in member_labels:
                continue
            member_labels.add(by_id[value]["label"])
            member_ids.append(value)
            if len(member_ids) == 8:
                break
        heading = by_id[member_ids[0]]["label"] if member_ids else community["label"]
        lines.append(f"### {heading} 相关职责")
        lines.append("")
        for node_id in member_ids:
            node = by_id[node_id]
            description = str(node.get("description_zh") or "").strip()
            lines.append(f"- **{node['label']}**" + (f"：{description}" if description else ""))
        lines.append("")
    if len(communities) > REPORT_COMMUNITY_LIMIT:
        lines.append("> 为保持阅读节奏，这里只展开最主要的职责群；图查询仍会使用完整关系。")
        lines.append("")
    lines.extend(
        [
            "## 围绕任务继续缩小范围",
            "",
            "```powershell",
            '& PYTHON scripts\\ckb.py query --out OUTPUT "职责关键词" --budget 1500',
            '& PYTHON scripts\\ckb.py path --out OUTPUT "起点类或函数" "目标类或函数"',
            '& PYTHON scripts\\ckb.py explain --out OUTPUT "类名、函数名或职责关键词"',
            "```",
            "",
            "查询会先选择与问题最相关的代码，再沿真实关系扩展到预算允许的范围。",
            "",
        ]
    )
    return "\n".join(lines)


def project_graphify(output: Path, canonical: dict[str, Any]) -> dict[str, Any]:
    """Build the Graphify-compatible projection from the reviewed canonical graph."""
    root = output / "graphify-out"
    root.mkdir(parents=True, exist_ok=True)
    entity_by_id = {entity["id"]: entity for entity in canonical["entities"]}
    nodes = [_graphify_node(entity) for entity in canonical["entities"]]
    links = [_graphify_link(link, entity_by_id) for link in canonical["links"]]
    nodes.sort(key=lambda item: item["id"])
    links.sort(key=lambda item: item["id"])

    graph = _build_networkx(nodes, links)
    _nx, cluster, label_communities_by_hub, score_all = _networkx_modules()
    grouped = cluster(graph)
    labels = label_communities_by_hub(graph, grouped)
    scores = score_all(graph.to_undirected(), grouped)
    communities = _community_records(graph, grouped, labels, scores)
    community_by_node = {
        node_id: community["id"]
        for community in communities
        for node_id in community["members"]
    }
    for node in nodes:
        node["community"] = community_by_node[node["id"]]
        node["community_name"] = labels[community_by_node[node["id"]]]
        node["norm_label"] = node["label"].casefold()

    graph_doc = {
        "directed": True,
        "multigraph": True,
        "graph": {
            "schema": "graphify-node-link",
            "schema_version": GRAPHIFY_PROJECTION_SCHEMA,
            "generator": "code-knowledge-builder",
            "graphify_upstream": GRAPHIFY_UPSTREAM,
            "graphify_commit": GRAPHIFY_COMMIT,
            "graphify_version": GRAPHIFY_VERSION,
            "pipeline": GRAPHIFY_PIPELINE,
            "source_graph": str((output / "graph.json").resolve()),
            "scope": canonical["scope"].get("mode"),
        },
        "nodes": nodes,
        "links": links,
        "hyperedges": [],
        "built_at_commit": canonical["repository"]["commit"],
    }
    graph_path = root / "graph.json"
    communities_path = root / "communities.json"
    report_path = root / "GRAPH_REPORT.md"
    json_write(graph_path, graph_doc)
    json_write(
        communities_path,
        {
            "schema_version": GRAPHIFY_PROJECTION_SCHEMA,
            "graphify_commit": GRAPHIFY_COMMIT,
            "communities": communities,
        },
    )
    report_path.write_text(
        _report(canonical, nodes, links, communities, graph),
        encoding="utf-8",
        newline="\n",
    )
    record = {
        "schema_version": GRAPHIFY_PROJECTION_SCHEMA,
        "status": "projected",
        "root": str(root.resolve()),
        "graph": str(graph_path.resolve()),
        "graph_sha256": sha256_file(graph_path),
        "communities": str(communities_path.resolve()),
        "communities_sha256": sha256_file(communities_path),
        "report": str(report_path.resolve()),
        "report_sha256": sha256_file(report_path),
        "node_count": len(nodes),
        "link_count": len(links),
        "community_count": len(communities),
        "confidence_counts": dict(sorted(Counter(link["confidence"] for link in links).items())),
        "graphify_upstream": GRAPHIFY_UPSTREAM,
        "graphify_commit": GRAPHIFY_COMMIT,
        "graphify_version": GRAPHIFY_VERSION,
        "networkx_version": _nx.__version__,
        "generated_at_utc": utc_now(),
    }
    json_write(root / "projection.json", record)
    return record


def audit_graphify(output: Path, canonical: dict[str, Any], record: dict[str, Any]) -> list[dict[str, Any]]:
    """Validate full-set parity, source provenance, confidence, and communities."""
    errors: list[dict[str, Any]] = []
    root = output / "graphify-out"
    paths = {
        "graph": root / "graph.json",
        "communities": root / "communities.json",
        "report": root / "GRAPH_REPORT.md",
        "projection": root / "projection.json",
    }
    for name, path in paths.items():
        if not path.is_file():
            errors.append({"reason": f"graphify-{name}-missing", "path": str(path)})
    if errors:
        return errors

    projected = json_load(paths["graph"])
    community_doc = json_load(paths["communities"])
    projection_doc = json_load(paths["projection"])
    if projection_doc != record:
        errors.append({"reason": "graphify-projection-record-mismatch"})
    canonical_entities = {entity["id"]: entity for entity in canonical["entities"]}
    projected_nodes = {node["id"]: node for node in projected.get("nodes", [])}
    if set(projected_nodes) != set(canonical_entities):
        errors.append(
            {
                "reason": "graphify-node-set-mismatch",
                "missing": sorted(set(canonical_entities) - set(projected_nodes)),
                "extra": sorted(set(projected_nodes) - set(canonical_entities)),
            }
        )
    for entity_id in sorted(set(canonical_entities) & set(projected_nodes)):
        entity = canonical_entities[entity_id]
        node = projected_nodes[entity_id]
        source_range = entity.get("range", {})
        expected = {
            "source_file": entity.get("path"),
            "source_location": _source_location(entity),
            "commit": entity.get("commit"),
            "blob": entity.get("blob"),
            "classification": entity.get("classification"),
            "owner_page_id": entity.get("owner_page_id"),
            "source_range": {
                "start_byte": source_range.get("start_byte"),
                "end_byte": source_range.get("end_byte"),
                "start_line": source_range.get("start_line"),
                "end_line": source_range.get("end_line"),
            },
        }
        if any(node.get(key) != value for key, value in expected.items()):
            errors.append({"reason": "graphify-node-provenance-mismatch", "id": entity_id})

    canonical_links = {link["id"]: link for link in canonical["links"]}
    projected_links = {link["id"]: link for link in projected.get("links", [])}
    if set(projected_links) != set(canonical_links):
        errors.append(
            {
                "reason": "graphify-link-set-mismatch",
                "missing": sorted(set(canonical_links) - set(projected_links)),
                "extra": sorted(set(projected_links) - set(canonical_links)),
            }
        )
    for link_id in sorted(set(canonical_links) & set(projected_links)):
        source = canonical_links[link_id]
        link = projected_links[link_id]
        if link.get("source") != source["source"] or link.get("target") != source["target"] or link.get("relation") != source.get("type"):
            errors.append({"reason": "graphify-link-fact-mismatch", "id": link_id})
        if link.get("confidence") not in GRAPHIFY_CONFIDENCE:
            errors.append({"reason": "graphify-confidence-invalid", "id": link_id})
        if not link.get("provider") or not link.get("source_file"):
            errors.append({"reason": "graphify-link-evidence-missing", "id": link_id})
        if link.get("source") not in projected_nodes or link.get("target") not in projected_nodes:
            errors.append({"reason": "graphify-link-dangling", "id": link_id})

    memberships = [
        node_id
        for community in community_doc.get("communities", [])
        for node_id in community.get("members", [])
    ]
    if len(memberships) != len(set(memberships)) or set(memberships) != set(projected_nodes):
        errors.append({"reason": "graphify-community-cover-mismatch"})
    for community in community_doc.get("communities", []):
        if community.get("membership_sha256") != _canonical_json_sha256(sorted(community.get("members", []))):
            errors.append({"reason": "graphify-community-signature-mismatch", "id": community.get("id")})
    if record.get("community_count") != len(community_doc.get("communities", [])):
        errors.append({"reason": "graphify-community-count-contract-mismatch"})

    if projected.get("built_at_commit") != canonical["repository"]["commit"]:
        errors.append({"reason": "graphify-commit-mismatch"})
    graph_meta = projected.get("graph", {})
    if graph_meta.get("graphify_commit") != GRAPHIFY_COMMIT or graph_meta.get("pipeline") != GRAPHIFY_PIPELINE:
        errors.append({"reason": "graphify-upstream-provenance-mismatch"})
    if record.get("graphify_commit") != GRAPHIFY_COMMIT or record.get("graphify_version") != GRAPHIFY_VERSION:
        errors.append({"reason": "graphify-projection-upstream-mismatch"})
    hash_expectations = {
        "graph_sha256": paths["graph"],
        "communities_sha256": paths["communities"],
        "report_sha256": paths["report"],
    }
    for field, path in hash_expectations.items():
        if record.get(field) != sha256_file(path):
            errors.append({"reason": f"graphify-{field}-mismatch"})
    if record.get("node_count") != len(projected_nodes) or record.get("link_count") != len(projected_links):
        errors.append({"reason": "graphify-count-contract-mismatch"})
    report = paths["report"].read_text(encoding="utf-8")
    if GRAPHIFY_COMMIT in report or canonical["repository"]["commit"] in report:
        errors.append({"reason": "graphify-report-exposes-machine-commit"})
    required_headings = ("# 项目关系导览", "## 建议先看的代码", "## 按职责群浏览", "## 围绕任务继续缩小范围")
    if any(heading not in report for heading in required_headings):
        errors.append({"reason": "graphify-human-report-incomplete"})
    if any(marker in report for marker in ("degree `", "cohesion=", "分类 `", "EXTRACTED：", "INFERRED：", "AMBIGUOUS：")):
        errors.append({"reason": "graphify-report-exposes-machine-properties"})
    return errors


def _load_projected_graph(output: Path) -> tuple[dict[str, Any], dict[str, dict[str, Any]], list[dict[str, Any]]]:
    path = output / "graphify-out" / "graph.json"
    if not path.is_file():
        raise CkbError(f"finalize must create Graphify projection first: {path}")
    graph = json_load(path)
    nodes = {node["id"]: node for node in graph.get("nodes", [])}
    links = graph.get("links", [])
    if not nodes:
        raise CkbError(f"Graphify projection has no nodes: {path}")
    return graph, nodes, links


def _terms(text: str) -> list[str]:
    terms = {
        token.casefold()
        for token in re.findall(r"[\w.$:/\\-]+", text, flags=re.UNICODE)
        if len(token) >= 2
    }
    # Standard-library deterministic CJK segmentation: retain each complete run
    # and add adjacent bigrams, so "订单库存处理" can match separate "订单" and
    # "库存" evidence without jieba, an LLM, or host-specific tokenization.
    for run in re.findall(r"[\u3400-\u9fff]+", text):
        terms.update(run[index : index + 2] for index in range(max(0, len(run) - 1)))
    return sorted(terms, key=lambda value: (-len(value), value))


def _seed_scores(question: str, nodes: dict[str, dict[str, Any]]) -> list[tuple[int, str]]:
    terms = _terms(question)
    lowered_question = question.casefold()
    scored: list[tuple[int, str]] = []
    for node_id, node in nodes.items():
        label = str(node.get("label", "")).casefold()
        qname = str(node.get("qualified_name", "")).casefold()
        path = str(node.get("source_file", "")).casefold()
        description = str(node.get("description_zh", "")).casefold()
        haystacks = (label, qname, path, description)
        score = 0
        if lowered_question in haystacks or any(value and value in lowered_question for value in (label, qname)):
            score += 100
        for term in terms:
            if term == label or term == qname:
                score += 30
            elif term in label or term in qname:
                score += 12
            elif term in path:
                score += 6
            elif term in description:
                score += 3
        if score:
            scored.append((score, node_id))
    return sorted(scored, key=lambda value: (-value[0], value[1]))


def _adjacency(nodes: dict[str, dict[str, Any]], links: list[dict[str, Any]]) -> dict[str, list[tuple[str, dict[str, Any]]]]:
    result: dict[str, list[tuple[str, dict[str, Any]]]] = defaultdict(list)
    for link in links:
        if link["source"] in nodes and link["target"] in nodes:
            result[link["source"]].append((link["target"], link))
            result[link["target"]].append((link["source"], link))
    for node_id in result:
        result[node_id].sort(key=lambda row: (row[0], row[1]["id"]))
    return result


def _query_size(nodes: Iterable[dict[str, Any]], links: Iterable[dict[str, Any]]) -> int:
    payload = {"nodes": list(nodes), "links": list(links)}
    return math.ceil(len(json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")) / 3)


def query_graph(output: Path, question: str, budget: int = QUERY_DEFAULT_BUDGET, dfs: bool = False) -> dict[str, Any]:
    if budget <= 0:
        raise CkbError("query budget must be positive")
    _graph, nodes, links = _load_projected_graph(output)
    scored = _seed_scores(question, nodes)
    if not scored:
        raise CkbError(f"no Graphify node matched query: {question}")
    seeds = [node_id for _score, node_id in scored[:5]]
    adjacency = _adjacency(nodes, links)
    primary_seed = next((seed for seed in seeds if adjacency.get(seed)), seeds[0])
    # Traverse from one structurally connected seed. Enqueuing all fuzzy seeds
    # first spends a small budget on disconnected labels before BFS can include
    # the relations that explain why the first match matters.
    frontier: deque[tuple[str, int]] = deque([(primary_seed, 0)])
    selected: list[str] = []
    selected_set: set[str] = set()
    max_depth = 4
    while frontier:
        node_id, depth = frontier.pop() if dfs else frontier.popleft()
        if node_id in selected_set:
            continue
        candidate_ids = selected + [node_id]
        candidate_set = set(candidate_ids)
        candidate_links = [link for link in links if link["source"] in candidate_set and link["target"] in candidate_set]
        if selected and _query_size((nodes[value] for value in candidate_ids), candidate_links) > budget:
            continue
        selected.append(node_id)
        selected_set.add(node_id)
        if depth >= max_depth:
            continue
        neighbors = adjacency.get(node_id, [])
        ordered = reversed(neighbors) if dfs else neighbors
        for neighbor, _link in ordered:
            if neighbor not in selected_set:
                frontier.append((neighbor, depth + 1))
    selected_links = [link for link in links if link["source"] in selected_set and link["target"] in selected_set]
    selected_nodes = [nodes[node_id] for node_id in selected]
    files = sorted({node.get("source_file") for node in selected_nodes if node.get("source_file")})
    result = {
        "schema_version": GRAPHIFY_PROJECTION_SCHEMA,
        "status": "passed",
        "question": question,
        "traversal": "dfs" if dfs else "bfs",
        "budget": budget,
        "estimated_tokens": _query_size(selected_nodes, selected_links),
        "seed_ids": seeds,
        "primary_seed_id": primary_seed,
        "nodes": selected_nodes,
        "links": selected_links,
        "source_files": files,
        "graphify_commit": GRAPHIFY_COMMIT,
    }
    query_dir = output / "graphify-out" / "queries"
    query_dir.mkdir(parents=True, exist_ok=True)
    query_id = hashlib.sha256(f"{question}\0{budget}\0{dfs}".encode("utf-8")).hexdigest()[:16]
    json_write(query_dir / f"query-{query_id}.json", result)
    result["record"] = str((query_dir / f"query-{query_id}.json").resolve())
    return result


def _resolve_node(term: str, nodes: dict[str, dict[str, Any]]) -> str:
    if term in nodes:
        return term
    folded = term.casefold()
    exact = sorted(
        node_id
        for node_id, node in nodes.items()
        if folded in {str(node.get("label", "")).casefold(), str(node.get("qualified_name", "")).casefold()}
    )
    if len(exact) == 1:
        return exact[0]
    exact_pages = [node_id for node_id in exact if nodes[node_id].get("classification") == "page"]
    if len(exact_pages) == 1:
        return exact_pages[0]
    partial = sorted(
        node_id
        for node_id, node in nodes.items()
        if folded in str(node.get("label", "")).casefold()
        or folded in str(node.get("qualified_name", "")).casefold()
        or folded in str(node.get("source_file", "")).casefold()
    )
    candidates = exact or partial
    candidate_pages = [node_id for node_id in candidates if nodes[node_id].get("classification") == "page"]
    if len(candidate_pages) == 1:
        return candidate_pages[0]
    if len(candidates) != 1:
        raise CkbError(f"node selector must match exactly one node: {term}; candidates={candidates[:20]}")
    return candidates[0]


def shortest_path(output: Path, source: str, target: str) -> dict[str, Any]:
    _graph, nodes, links = _load_projected_graph(output)
    source_id = _resolve_node(source, nodes)
    target_id = _resolve_node(target, nodes)
    adjacency = _adjacency(nodes, links)
    queue: deque[str] = deque([source_id])
    previous: dict[str, tuple[str, str] | None] = {source_id: None}
    while queue and target_id not in previous:
        current = queue.popleft()
        for neighbor, link in adjacency.get(current, []):
            if neighbor not in previous:
                previous[neighbor] = (current, link["id"])
                queue.append(neighbor)
    if target_id not in previous:
        raise CkbError(f"no graph path between {source} and {target}")
    node_ids: list[str] = []
    link_ids: list[str] = []
    cursor = target_id
    while True:
        node_ids.append(cursor)
        step = previous[cursor]
        if step is None:
            break
        cursor, link_id = step
        link_ids.append(link_id)
    node_ids.reverse()
    link_ids.reverse()
    link_by_id = {link["id"]: link for link in links}
    return {
        "schema_version": GRAPHIFY_PROJECTION_SCHEMA,
        "status": "passed",
        "source": source_id,
        "target": target_id,
        "node_ids": node_ids,
        "nodes": [nodes[node_id] for node_id in node_ids],
        "links": [link_by_id[link_id] for link_id in link_ids],
        "hop_count": len(link_ids),
        "graphify_commit": GRAPHIFY_COMMIT,
    }


def explain_node(output: Path, selector: str) -> dict[str, Any]:
    _graph, nodes, links = _load_projected_graph(output)
    node_id = _resolve_node(selector, nodes)
    related = [link for link in links if link["source"] == node_id or link["target"] == node_id]
    related.sort(key=lambda item: (item["relation"], item["id"]))
    neighbor_ids = sorted(
        {
            link["target"] if link["source"] == node_id else link["source"]
            for link in related
        }
    )
    return {
        "schema_version": GRAPHIFY_PROJECTION_SCHEMA,
        "status": "passed",
        "node": nodes[node_id],
        "neighbors": [nodes[value] for value in neighbor_ids],
        "links": related,
        "graphify_commit": GRAPHIFY_COMMIT,
    }

"""Deterministic staging guidance for CKB human-readable page contracts.

This module never writes the human/markdown projections or either SQLite
index.  It reads one bounded source draft when supplementing or revising and
renders an in-memory candidate that is immediately checked by the frozen
``human_page_templates`` registry.
"""

from __future__ import annotations

import hashlib
import json
from pathlib import Path
import re
import os
import shutil
from typing import Any, Mapping, Sequence

from .common import CkbError
from .human_page_templates import (
    HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
    HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION,
    HumanPageTemplateContract,
    SectionContract,
    get_human_page_template,
    human_page_section_document,
    human_page_template_registry_sha256,
    validate_human_page,
)


HUMAN_PAGE_AUTHORING_SCHEMA_VERSION = 3
HUMAN_PAGE_AUTHORING_MODES = ("new", "supplement", "revise")


_HEADING_RE = re.compile(r"^(#{1,6})[ \t]+(.+?)[ \t]*#*[ \t]*$")
_SHA256_RE = re.compile(r"^[0-9a-f]{64}$")
_COMMON_FIELDS = {
    "schema_version",
    "contract_version",
    "page_type",
    "mode",
    "evidence",
    "validation_context",
    "applicability_boundary",
}
_MODE_FIELDS = {
    "new": _COMMON_FIELDS | {"title", "sections"},
    "supplement": _COMMON_FIELDS | {"source_path", "source_sha256", "sections", "title"},
    "revise": _COMMON_FIELDS | {"source_path", "source_sha256", "revisions"},
}


def _error(reason: str, message: str, **fields: Any) -> dict[str, Any]:
    return {"reason": reason, "message": message, **fields}


def _failed(operation: str, reason: str, message: str, **fields: Any) -> dict[str, Any]:
    return {
        "errors": [_error(reason, message, **fields)],
        "operation": operation,
        "schema_version": HUMAN_PAGE_AUTHORING_SCHEMA_VERSION,
        "status": "failed",
    }


def _missing(operation: str, page_type: str, mode: str, fields: Sequence[str]) -> dict[str, Any]:
    return {
        "missing_fields": sorted(set(fields)),
        "mode": mode,
        "operation": operation,
        "page_type": page_type,
        "schema_version": HUMAN_PAGE_AUTHORING_SCHEMA_VERSION,
        "status": "missing-fields",
    }


def _contract_result(
    operation: str,
    page_type: object,
    mode: object,
    *,
    contract_version: object = HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
    schema_version: object = HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION,
) -> tuple[HumanPageTemplateContract | None, dict[str, Any] | None]:
    mode_text = str(mode or "").strip()
    if mode_text not in HUMAN_PAGE_AUTHORING_MODES:
        return None, _failed(
            operation,
            "unknown-mode",
            f"未知人类页面编写模式：{mode_text}。",
            available=list(HUMAN_PAGE_AUTHORING_MODES),
        )
    try:
        contract_schema = int(schema_version)
    except (TypeError, ValueError):
        contract_schema = -1
    if (
        contract_schema != HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION
        or str(contract_version) != HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION
    ):
        return None, _failed(
            operation,
            "contract-version-incompatible",
            "人类页面模板合同版本不兼容；旧 1.0.0 输入必须显式按 V3 章节重写。",
            actual={"schema_version": schema_version, "contract_version": contract_version},
            expected={
                "schema_version": HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION,
                "contract_version": HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
            },
            migration={"from": "1.0.0", "to": HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION, "mode": "explicit-rewrite"},
        )
    try:
        return get_human_page_template(str(page_type or "")), None
    except CkbError as exc:  # get_human_page_template owns the stable type list.
        return None, _failed(operation, "unknown-page-type", str(exc))


def _field_slot(field: str, field_type: str, purpose: str) -> dict[str, str]:
    return {"field": field, "type": field_type, "purpose": purpose}


def _section_slot(section: SectionContract) -> dict[str, Any]:
    value: dict[str, Any] = {
        "human_summary": "",
        "key_entities": [],
        "links": [],
        "metrics": [],
        "source_refs": [],
        "machine_evidence_refs": [],
    }
    if section.heading_pattern:
        value["heading"] = ""
    return value


def init_page_author(
    page_type: str,
    mode: str,
    *,
    contract_version: str = HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
    schema_version: int = HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION,
) -> dict[str, Any]:
    """Return only the minimum typed fields for one page type and mode."""

    contract, failure = _contract_result(
        "init",
        page_type,
        mode,
        contract_version=contract_version,
        schema_version=schema_version,
    )
    if failure:
        return failure
    assert contract is not None

    skeleton: dict[str, Any] = {
        "schema_version": HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION,
        "contract_version": HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
        "page_type": contract.page_type,
        "mode": mode,
        "evidence": {field: "" for field in contract.evidence_requirements.required_fields},
        "validation_context": {"sections": {}, "current_facts": []},
        "applicability_boundary": contract.applicability_boundary,
    }
    fields = [
        _field_slot(f"evidence.{field}", "non-empty", "满足页面合同的来源或验证字段。")
        for field in contract.evidence_requirements.required_fields
    ]

    if mode == "new":
        skeleton["title"] = ""
        skeleton["sections"] = {
            section.section_id: _section_slot(section) for section in contract.required_sections
        }
        fields.insert(0, _field_slot("title", "non-empty-string", "页面唯一一级标题。"))
        fields[1:1] = [
            _field_slot(
                f"sections.{section.section_id}.human_summary",
                "non-empty-human-markdown",
                "只填写人类可见摘要；完整命令、日志、哈希、SQLite、manifest、maintain 和回滚探针写入 machine_evidence_refs。",
            )
            for section in contract.required_sections
        ]
        for section in contract.required_sections:
            if section.heading_pattern:
                fields.append(
                    _field_slot(
                        f"sections.{section.section_id}.heading",
                        f"regex:{section.heading_pattern}",
                        "为动态章节提供满足冻结合同的标题。",
                    )
                )
    elif mode == "supplement":
        skeleton.update({"source_path": "", "source_sha256": "", "sections": {}})
        fields[0:0] = [
            _field_slot("source_path", "workspace-relative-path", "只读打开现有草稿或受管页面。"),
            _field_slot("source_sha256", "sha256", "防止 inspect 后目标内容漂移。"),
            _field_slot("sections", "missing-section-map", "只填写 inspect 返回的缺失章节。"),
        ]
    else:
        skeleton.update({"source_path": "", "source_sha256": "", "revisions": []})
        fields[0:0] = [
            _field_slot("source_path", "workspace-relative-path", "只读打开现有草稿或受管页面。"),
            _field_slot("source_sha256", "sha256", "防止 inspect 后目标内容漂移。"),
            _field_slot(
                "revisions",
                "array[{section_id,current,human_summary,source_refs,machine_evidence_refs,key_entities,links,metrics}]",
                "逐项说明要替换的当前段落、人类摘要、来源与不投影的 L4 机器证据引用。",
            ),
        ]

    return {
        "contract_version": HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
        "fields": fields,
        "mode": mode,
        "operation": "init",
        "page_type": contract.page_type,
        "registry_sha256": human_page_template_registry_sha256(),
        "schema_version": HUMAN_PAGE_AUTHORING_SCHEMA_VERSION,
        "section_constraints": {
            section.section_id: human_page_section_document(section)
            for section in contract.required_sections + contract.optional_sections
        },
        "skeleton": skeleton,
        "status": "ready",
    }


def _resolve_within(path_value: str | Path, workspace_root: str | Path) -> tuple[Path | None, dict[str, Any] | None]:
    root = Path(workspace_root).resolve()
    candidate = Path(path_value)
    if not candidate.is_absolute():
        candidate = root / candidate
    candidate = candidate.resolve()
    if candidate != root and root not in candidate.parents:
        return None, _failed(
            "inspect",
            "path-outside-workspace",
            "页面路径越过 workspace_root。",
            path=str(candidate),
            workspace_root=str(root),
        )
    if not candidate.is_file():
        return None, _failed("inspect", "source-not-found", "页面来源不是可读取文件。", path=str(candidate))
    return candidate, None


def _sha256_text(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def _document_sections(markdown: str) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    lines = markdown.splitlines()
    headings: list[dict[str, Any]] = []
    fence: str | None = None
    for index, line in enumerate(lines):
        stripped = line.lstrip()
        marker = stripped[:3]
        if marker in {"```", "~~~"}:
            if fence is None:
                fence = marker
            elif marker == fence:
                fence = None
            continue
        if fence is not None:
            continue
        match = _HEADING_RE.match(line.strip())
        if match:
            headings.append(
                {"level": len(match.group(1)), "text": match.group(2).strip(), "line": index + 1, "index": index}
            )
    sections: list[dict[str, Any]] = []
    for position, heading in enumerate(headings):
        end = len(lines)
        for following in headings[position + 1 :]:
            if int(following["level"]) <= int(heading["level"]):
                end = int(following["index"])
                break
        body = "\n".join(lines[int(heading["index"]) + 1 : end]).strip()
        sections.append({**heading, "body": body, "end_index": end})
    return headings, sections


def _matches(section: SectionContract, heading: Mapping[str, Any]) -> bool:
    if int(heading["level"]) != section.level:
        return False
    text = str(heading["text"])
    if section.heading_pattern:
        return re.fullmatch(section.heading_pattern, text) is not None
    return text == section.heading


def _managed_source(path: Path, workspace_root: Path) -> bool:
    relative = path.resolve().relative_to(workspace_root.resolve())
    return bool({"human", "markdown"} & set(relative.parts)) or path.suffix.casefold() in {
        ".sqlite",
        ".db",
    }


def inspect_page_author(
    page_type: str,
    mode: str,
    source_path: str | Path,
    *,
    workspace_root: str | Path,
    expected_sha256: str | None = None,
    contract_version: str = HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
    schema_version: int = HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION,
) -> dict[str, Any]:
    """Read one bounded source and report contract fields without editing it."""

    contract, failure = _contract_result(
        "inspect",
        page_type,
        mode,
        contract_version=contract_version,
        schema_version=schema_version,
    )
    if failure:
        return failure
    assert contract is not None
    source, failure = _resolve_within(source_path, workspace_root)
    if failure:
        return failure
    assert source is not None
    try:
        markdown = source.read_text(encoding="utf-8-sig")
    except (OSError, UnicodeError) as exc:
        return _failed("inspect", "source-unreadable", f"页面来源读取失败：{exc}", path=str(source))
    digest = _sha256_text(markdown)
    if expected_sha256 is not None and expected_sha256.casefold() != digest:
        return _failed(
            "inspect",
            "target-drift",
            "页面来源在 inspect 前后发生漂移。",
            expected_sha256=expected_sha256,
            actual_sha256=digest,
        )

    headings, sections = _document_sections(markdown)
    satisfied: list[str] = []
    missing: list[str] = []
    conflicts: list[dict[str, Any]] = []
    h1 = [heading for heading in headings if heading["level"] == 1]
    if len(h1) == 1:
        satisfied.append("title")
    else:
        missing.append("title")
        conflicts.append({"field": "title", "reason": "title-heading-count", "count": len(h1)})
    for required in contract.required_sections:
        matches = [section for section in sections if _matches(required, section)]
        field = f"sections.{required.section_id}.human_summary"
        if len(matches) == 1 and str(matches[0]["body"]).strip():
            satisfied.append(field)
        else:
            missing.append(field)
        if len(matches) > 1 and not required.repeatable:
            conflicts.append(
                {
                    "field": field,
                    "reason": "duplicate-heading",
                    "lines": [item["line"] for item in matches],
                }
            )
        if len(matches) == 1 and not str(matches[0]["body"]).strip():
            conflicts.append({"field": field, "reason": "section-empty", "line": matches[0]["line"]})

    root = Path(workspace_root).resolve()
    managed = _managed_source(source, root)
    actions = ["render", "validate", "package"]
    return {
        "allowed_actions": actions,
        "conflict_fields": conflicts,
        "contract_version": HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
        "managed_page": managed,
        "missing_fields": missing,
        "mode": mode,
        "operation": "inspect",
        "page_type": contract.page_type,
        "satisfied_fields": satisfied,
        "schema_version": HUMAN_PAGE_AUTHORING_SCHEMA_VERSION,
        "source": {
            "path": str(source),
            "relative_path": source.relative_to(root).as_posix(),
            "sha256": digest,
        },
        "status": "conflicted" if conflicts else "ready",
    }


def _non_empty(value: Any) -> bool:
    if isinstance(value, str):
        return bool(value.strip())
    if isinstance(value, (list, tuple, dict)):
        return bool(value)
    return value is not None


def _validate_top_level(payload: Mapping[str, Any], mode: str) -> dict[str, Any] | None:
    unknown = sorted(set(payload) - _MODE_FIELDS[mode])
    if unknown:
        return _failed(
            "render",
            "unknown-field",
            "schema 化输入包含未知字段。",
            fields=unknown,
        )
    return None


def _section_by_id(contract: HumanPageTemplateContract) -> dict[str, SectionContract]:
    return {section.section_id: section for section in contract.required_sections + contract.optional_sections}


def _normalize_section_input(
    operation: str,
    section: SectionContract,
    value: Any,
) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    if not isinstance(value, Mapping):
        return None, _failed(operation, "field-type-invalid", "章节输入必须是对象。", field=f"sections.{section.section_id}")
    allowed = {
        "human_summary",
        "key_entities",
        "links",
        "metrics",
        "source_refs",
        "machine_evidence_refs",
    }
    if section.heading_pattern:
        allowed.add("heading")
    unknown = sorted(set(value) - allowed)
    if unknown:
        return None, _failed(
            operation,
            "unknown-field",
            "章节输入包含未知字段。",
            fields=[f"sections.{section.section_id}.{name}" for name in unknown],
        )
    human_summary = str(value.get("human_summary") or "").strip()
    heading = str(value.get("heading") or section.heading).strip()
    if section.heading_pattern and heading and re.fullmatch(section.heading_pattern, heading) is None:
        return None, _failed(
            operation,
            "heading-pattern-mismatch",
            "动态章节标题不符合冻结合同。",
            field=f"sections.{section.section_id}.heading",
            pattern=section.heading_pattern,
        )
    lists: dict[str, list[Any]] = {}
    for field in ("key_entities", "links", "metrics", "source_refs", "machine_evidence_refs"):
        item = value.get(field, [])
        if not isinstance(item, list):
            return None, _failed(
                operation,
                "field-type-invalid",
                "章节的实体、指标、链接和证据引用字段必须是数组。",
                field=f"sections.{section.section_id}.{field}",
            )
        lists[field] = list(item)
    return {"human_summary": human_summary, "heading": heading, **lists}, None


def _render_section(section: SectionContract, value: Mapping[str, Any]) -> str:
    return f"{'#' * section.level} {value['heading']}\n\n{value['human_summary']}"


def _section_validation_context(value: Mapping[str, Any]) -> dict[str, Any]:
    return {
        field: list(value.get(field, []))
        for field in ("key_entities", "links", "metrics", "source_refs", "machine_evidence_refs")
    }


def _canonical_reference(value: Mapping[str, Any]) -> dict[str, str]:
    result = {
        "kind": str(value.get("kind") or "").strip(),
        "purpose": str(value.get("purpose") or "").strip(),
        "target": str(value.get("target") or "").strip(),
    }
    digest = str(value.get("sha256") or "").strip().casefold()
    if digest:
        result["sha256"] = digest
    return result


def _section_evidence_document(
    contract: HumanPageTemplateContract,
    context: Mapping[str, Any],
) -> dict[str, Any]:
    sections_value = context.get("sections", {})
    assert isinstance(sections_value, Mapping)
    sections: list[dict[str, Any]] = []
    for section in contract.required_sections + contract.optional_sections:
        value = sections_value.get(section.section_id)
        if not isinstance(value, Mapping):
            continue
        source_refs = sorted(
            (_canonical_reference(item) for item in value.get("source_refs", []) if isinstance(item, Mapping)),
            key=lambda item: (item["target"], item["kind"], item["purpose"], item.get("sha256", "")),
        )
        machine_refs = sorted(
            (
                _canonical_reference(item)
                for item in value.get("machine_evidence_refs", [])
                if isinstance(item, Mapping)
            ),
            key=lambda item: (item["target"], item["kind"], item["purpose"], item.get("sha256", "")),
        )
        sections.append(
            {
                "disclosure_level": section.disclosure_level,
                "heading": section.heading,
                "machine_evidence_refs": machine_refs,
                "section_id": section.section_id,
                "source_refs": source_refs,
            }
        )
    return {"schema_version": 1, "sections": sections}


def _base_missing_fields(payload: Mapping[str, Any], contract: HumanPageTemplateContract) -> list[str]:
    missing: list[str] = []
    evidence = payload.get("evidence")
    if not isinstance(evidence, Mapping):
        missing.append("evidence")
    else:
        for field in contract.evidence_requirements.required_fields:
            if not _non_empty(evidence.get(field)):
                missing.append(f"evidence.{field}")
    context = payload.get("validation_context")
    if not isinstance(context, Mapping):
        missing.append("validation_context")
    return missing


def _load_source_for_render(
    payload: Mapping[str, Any], workspace_root: str | Path
) -> tuple[Path | None, str | None, dict[str, Any] | None]:
    source_value = payload.get("source_path")
    expected = str(payload.get("source_sha256") or "").casefold()
    missing = []
    if not _non_empty(source_value):
        missing.append("source_path")
    if not _SHA256_RE.fullmatch(expected):
        missing.append("source_sha256")
    if missing:
        return None, None, _missing("render", str(payload.get("page_type") or ""), str(payload.get("mode") or ""), missing)
    source, failure = _resolve_within(str(source_value), workspace_root)
    if failure:
        assert failure is not None
        failure["operation"] = "render"
        return None, None, failure
    assert source is not None
    try:
        markdown = source.read_text(encoding="utf-8-sig")
    except (OSError, UnicodeError) as exc:
        return None, None, _failed("render", "source-unreadable", f"页面来源读取失败：{exc}", path=str(source))
    actual = _sha256_text(markdown)
    if actual != expected:
        return None, None, _failed(
            "render",
            "target-drift",
            "页面来源在 inspect 后发生漂移。",
            expected_sha256=expected,
            actual_sha256=actual,
        )
    return source, markdown, None


_CONTEXT_FIELDS = {"sections", "current_facts"}
_VALIDATE_FIELDS = {
    "schema_version",
    "contract_version",
    "page_type",
    "markdown",
    "evidence",
    "validation_context",
    "applicability_boundary",
}
_STRUCTURE_REASONS = {
    "page-empty",
    "title-heading-count",
    "required-section-missing",
    "duplicate-heading",
    "process-meta-copy",
    "section-empty",
    "empty-section-must-be-omitted",
}
_BUDGET_REASONS = {
    "key-entity-budget",
    "source-link-budget",
    "section-key-entity-budget",
    "section-length-budget",
    "section-link-budget",
}
_LINK_REASONS = {
    "link-purpose-missing",
    "link-context-missing",
    "link-context-unused",
    "link-target-conflict",
    "link-target-duplicate",
    "section-link-target-type",
}
_CURRENT_FACT_REASONS = {"current-fact-unverified"}
_DISCLOSURE_REASONS = {"l4-evidence-leak", "l4-machine-evidence-rendered"}


def _validate_nested_input(
    operation: str,
    contract: HumanPageTemplateContract,
    evidence: Any,
    context: Any,
) -> dict[str, Any] | None:
    if not isinstance(evidence, Mapping):
        return None
    unknown_evidence = sorted(set(evidence) - set(contract.evidence_requirements.required_fields))
    if unknown_evidence:
        return _failed(
            operation,
            "unknown-field",
            "evidence 包含当前页面类型未定义的字段。",
            fields=[f"evidence.{field}" for field in unknown_evidence],
        )
    if not isinstance(context, Mapping):
        return None
    unknown_context = sorted(set(context) - _CONTEXT_FIELDS)
    if unknown_context:
        return _failed(
            operation,
            "unknown-field",
            "validation_context 包含未知字段。",
            fields=[f"validation_context.{field}" for field in unknown_context],
        )
    current_facts = context.get("current_facts", [])
    if isinstance(current_facts, list):
        for index, item in enumerate(current_facts):
            if not isinstance(item, Mapping):
                continue
            unknown = sorted(set(item) - {"claim", "source", "observed_at", "section_id"})
            if unknown:
                return _failed(
                    operation,
                    "unknown-field",
                    "validation_context.current_facts 条目包含未知字段。",
                    fields=[f"validation_context.current_facts[{index}].{name}" for name in unknown],
                )
    sections = context.get("sections", {})
    if isinstance(sections, Mapping):
        section_ids = set(_section_by_id(contract))
        unknown_sections = sorted(set(sections) - section_ids)
        if unknown_sections:
            return _failed(
                operation,
                "unknown-field",
                "validation_context.sections 包含当前页面类型未定义的章节。",
                fields=[f"validation_context.sections.{field}" for field in unknown_sections],
            )
        allowed_section = {"key_entities", "links", "metrics", "source_refs", "machine_evidence_refs"}
        for section_id, value in sections.items():
            if not isinstance(value, Mapping):
                continue
            unknown = sorted(set(value) - allowed_section)
            if unknown:
                return _failed(
                    operation,
                    "unknown-field",
                    "validation_context 章节条目包含未知字段。",
                    fields=[f"validation_context.sections.{section_id}.{name}" for name in unknown],
                )
            for field in ("links", "source_refs", "machine_evidence_refs"):
                entries = value.get(field, [])
                if not isinstance(entries, list):
                    continue
                for index, item in enumerate(entries):
                    if not isinstance(item, Mapping):
                        continue
                    unknown_ref = sorted(set(item) - {"target", "purpose", "kind", "sha256"})
                    if unknown_ref:
                        return _failed(
                            operation,
                            "unknown-field",
                            "章节链接或证据引用包含未知字段。",
                            fields=[
                                f"validation_context.sections.{section_id}.{field}[{index}].{name}"
                                for name in unknown_ref
                            ],
                        )
    return None


def _candidate_validation(
    contract: HumanPageTemplateContract,
    markdown: str,
    *,
    evidence: Any,
    context: Any,
    declared_boundary: Any,
) -> dict[str, Any]:
    missing: list[str] = []
    if not isinstance(evidence, Mapping):
        missing.append("evidence")
        evidence = {}
    for field in contract.evidence_requirements.required_fields:
        if not _non_empty(evidence.get(field)):
            missing.append(f"evidence.{field}")
    if not isinstance(context, Mapping):
        missing.append("validation_context")
        context = {}
    if missing:
        return _missing("validate", contract.page_type, "candidate", missing)

    base = validate_human_page(
        contract.page_type,
        markdown,
        context=context,
        contract_version=HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
        schema_version=HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION,
    )
    errors = list(base.get("errors", []))
    boundary_text = str(declared_boundary or "").strip()
    boundary_status = "passed"
    if boundary_text and boundary_text != contract.applicability_boundary:
        boundary_status = "failed"
        errors.append(
            _error(
                "applicability-boundary-drift",
                "输入适用边界与当前页面合同不一致。",
                expected=contract.applicability_boundary,
                actual=boundary_text,
            )
        )

    reasons = {str(error.get("reason")) for error in errors}

    def status_for(category: set[str]) -> str:
        return "failed" if reasons & category else "passed"

    checks = {
        "structure": {"status": status_for(_STRUCTURE_REASONS)},
        "budget": {
            "status": status_for(_BUDGET_REASONS),
            "key_entity_count": base.get("metrics", {}).get("key_entity_count"),
            "source_link_count": base.get("metrics", {}).get("source_link_count"),
        },
        "links": {"status": status_for(_LINK_REASONS)},
        "disclosure": {"status": status_for(_DISCLOSURE_REASONS)},
        "current_fact_evidence": {
            "status": status_for(_CURRENT_FACT_REASONS),
            "verified_count": base.get("metrics", {}).get("verified_current_fact_count"),
        },
        "contract_evidence": {
            "status": "passed",
            "required_fields": list(contract.evidence_requirements.required_fields),
        },
        "applicability_boundary": {
            "status": boundary_status,
            "value": contract.applicability_boundary,
        },
    }
    unclassified = reasons - _STRUCTURE_REASONS - _BUDGET_REASONS - _LINK_REASONS - _CURRENT_FACT_REASONS - _DISCLOSURE_REASONS - {
        "applicability-boundary-drift"
    }
    if unclassified:
        checks["validation_context"] = {"status": "failed", "reasons": sorted(unclassified)}
    else:
        checks["validation_context"] = {"status": "passed"}
    return {
        "checks": checks,
        "contract_version": HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
        "errors": errors,
        "metrics": base.get("metrics", {}),
        "operation": "validate",
        "page_type": contract.page_type,
        "registry_sha256": human_page_template_registry_sha256(),
        "schema_version": HUMAN_PAGE_AUTHORING_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
    }


def validate_page_author(payload: Mapping[str, Any]) -> dict[str, Any]:
    """Validate structure, budgets, links, evidence, and boundary in one result."""

    if not isinstance(payload, Mapping):
        return _failed("validate", "input-not-object", "validate 输入必须是 JSON 对象。")
    unknown = sorted(set(payload) - _VALIDATE_FIELDS)
    if unknown:
        return _failed(
            "validate",
            "unknown-field",
            "validate 输入包含未知字段。",
            fields=unknown,
        )
    contract, failure = _contract_result(
        "validate",
        payload.get("page_type"),
        "new",
        contract_version=payload.get("contract_version", HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION),
        schema_version=payload.get("schema_version", HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION),
    )
    if failure:
        return failure
    assert contract is not None
    failure = _validate_nested_input(
        "validate", contract, payload.get("evidence"), payload.get("validation_context")
    )
    if failure:
        return failure
    markdown = payload.get("markdown")
    if not isinstance(markdown, str) or not markdown.strip():
        return _missing("validate", contract.page_type, "candidate", ["markdown"])
    return _candidate_validation(
        contract,
        markdown,
        evidence=payload.get("evidence"),
        context=payload.get("validation_context"),
        declared_boundary=payload.get("applicability_boundary"),
    )


def render_page_author(payload: Mapping[str, Any], *, workspace_root: str | Path = ".") -> dict[str, Any]:
    """Render a complete candidate from schema input and validate it immediately."""

    if not isinstance(payload, Mapping):
        return _failed("render", "input-not-object", "render 输入必须是 JSON 对象。")
    contract, failure = _contract_result(
        "render",
        payload.get("page_type"),
        payload.get("mode"),
        contract_version=payload.get("contract_version", HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION),
        schema_version=payload.get("schema_version", HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION),
    )
    if failure:
        return failure
    assert contract is not None
    mode = str(payload["mode"])
    failure = _validate_top_level(payload, mode)
    if failure:
        return failure
    failure = _validate_nested_input(
        "render", contract, payload.get("evidence"), payload.get("validation_context")
    )
    if failure:
        return failure
    declared_boundary = str(payload.get("applicability_boundary") or "").strip()
    if declared_boundary and declared_boundary != contract.applicability_boundary:
        return _failed(
            "render",
            "target-drift",
            "输入适用边界与当前页面合同不一致。",
            expected=contract.applicability_boundary,
            actual=declared_boundary,
        )

    missing = _base_missing_fields(payload, contract)
    section_contracts = _section_by_id(contract)
    markdown = ""
    source: Path | None = None
    source_sha256: str | None = None
    authored_section_contexts: dict[str, dict[str, Any]] = {}

    if mode == "new":
        title = str(payload.get("title") or "").strip()
        sections_value = payload.get("sections")
        if not title:
            missing.append("title")
        if not isinstance(sections_value, Mapping):
            missing.append("sections")
            sections_value = {}
        unknown_sections = sorted(set(sections_value) - set(section_contracts))
        if unknown_sections:
            return _failed(
                "render",
                "unknown-field",
                "sections 包含当前页面类型未定义的字段。",
                fields=[f"sections.{field}" for field in unknown_sections],
            )
        normalized: dict[str, dict[str, Any]] = {}
        for section in contract.required_sections:
            value = sections_value.get(section.section_id)
            if value is None:
                missing.append(f"sections.{section.section_id}.human_summary")
                if section.heading_pattern:
                    missing.append(f"sections.{section.section_id}.heading")
                continue
            item, failure = _normalize_section_input("render", section, value)
            if failure:
                return failure
            assert item is not None
            if not item["human_summary"]:
                missing.append(f"sections.{section.section_id}.human_summary")
            if section.heading_pattern and not item["heading"]:
                missing.append(f"sections.{section.section_id}.heading")
            normalized[section.section_id] = item
            authored_section_contexts[section.section_id] = _section_validation_context(item)
        for section in contract.optional_sections:
            if section.section_id not in sections_value:
                continue
            item, failure = _normalize_section_input("render", section, sections_value[section.section_id])
            if failure:
                return failure
            assert item is not None
            if not item["human_summary"]:
                missing.append(f"sections.{section.section_id}.human_summary")
            normalized[section.section_id] = item
            authored_section_contexts[section.section_id] = _section_validation_context(item)
        if missing:
            return _missing("render", contract.page_type, mode, missing)
        rendered_sections = [
            _render_section(section, normalized[section.section_id])
            for section in contract.required_sections + contract.optional_sections
            if section.section_id in normalized
        ]
        markdown = f"# {title}\n\n" + "\n\n".join(rendered_sections) + "\n"
    elif mode == "supplement":
        if "title" in payload:
            return _failed(
                "render",
                "duplicate-title",
                "补充模式复用来源页标题，不接收或复制一级标题。",
                field="title",
            )
        source, existing, failure = _load_source_for_render(payload, workspace_root)
        if failure:
            return failure
        assert source is not None and existing is not None
        source_sha256 = _sha256_text(existing)
        sections_value = payload.get("sections")
        if not isinstance(sections_value, Mapping) or not sections_value:
            missing.append("sections")
            sections_value = {}
        unknown_sections = sorted(set(sections_value) - set(section_contracts))
        if unknown_sections:
            return _failed(
                "render",
                "unknown-field",
                "sections 包含当前页面类型未定义的字段。",
                fields=[f"sections.{field}" for field in unknown_sections],
            )
        _headings, existing_sections = _document_sections(existing)
        additions: list[str] = []
        for section_id, value in sections_value.items():
            section = section_contracts[str(section_id)]
            if any(_matches(section, item) for item in existing_sections):
                return _failed(
                    "render",
                    "field-already-satisfied",
                    "补充模式只接收当前页面缺少的章节。",
                    field=f"sections.{section_id}",
                )
            item, failure = _normalize_section_input("render", section, value)
            if failure:
                return failure
            assert item is not None
            if not item["human_summary"]:
                missing.append(f"sections.{section_id}.human_summary")
            additions.append(_render_section(section, item))
            authored_section_contexts[str(section_id)] = _section_validation_context(item)
        if missing:
            return _missing("render", contract.page_type, mode, missing)
        markdown = existing.rstrip() + "\n\n" + "\n\n".join(additions) + "\n"
    else:
        source, existing, failure = _load_source_for_render(payload, workspace_root)
        if failure:
            return failure
        assert source is not None and existing is not None
        source_sha256 = _sha256_text(existing)
        revisions = payload.get("revisions")
        if not isinstance(revisions, list) or not revisions:
            missing.append("revisions")
            revisions = []
        normalized_revisions: list[dict[str, Any]] = []
        for index, revision in enumerate(revisions):
            if not isinstance(revision, Mapping):
                return _failed(
                    "render",
                    "field-type-invalid",
                    "revisions 条目必须是对象。",
                    field=f"revisions[{index}]",
                )
            allowed_revision = {
                "section_id",
                "current",
                "human_summary",
                "key_entities",
                "links",
                "metrics",
                "source_refs",
                "machine_evidence_refs",
            }
            unknown = sorted(set(revision) - allowed_revision)
            if unknown:
                return _failed(
                    "render",
                    "unknown-field",
                    "revisions 条目包含未知字段。",
                    fields=[f"revisions[{index}].{field}" for field in unknown],
                )
            item: dict[str, Any] = {
                name: str(revision.get(name) or "").strip()
                for name in ("section_id", "current", "human_summary")
            }
            for name in ("section_id", "current", "human_summary"):
                if not item[name]:
                    missing.append(f"revisions[{index}].{name}")
            for name in ("key_entities", "links", "metrics", "source_refs", "machine_evidence_refs"):
                value = revision.get(name, [])
                if not isinstance(value, list):
                    return _failed(
                        "render",
                        "field-type-invalid",
                        "revision 的实体、链接、来源和证据引用必须是数组。",
                        field=f"revisions[{index}].{name}",
                    )
                item[name] = list(value)
            if not item["source_refs"]:
                missing.append(f"revisions[{index}].source_refs")
            if item["section_id"] and item["section_id"] not in section_contracts:
                return _failed(
                    "render",
                    "unknown-field",
                    "revision 指向当前页面类型未定义的章节。",
                    field=f"revisions[{index}].section_id",
                )
            normalized_revisions.append(item)
        if missing:
            return _missing("render", contract.page_type, mode, missing)
        markdown = existing
        _headings, existing_sections = _document_sections(existing)
        for index, revision in enumerate(normalized_revisions):
            section = section_contracts[revision["section_id"]]
            matches = [item for item in existing_sections if _matches(section, item)]
            if len(matches) != 1 or revision["current"] not in str(matches[0]["body"]):
                return _failed(
                    "render",
                    "revision-target-missing",
                    "修订目标段落未在指定章节中唯一定位。",
                    field=f"revisions[{index}].current",
                    section_id=revision["section_id"],
                )
            if markdown.count(revision["current"]) != 1:
                return _failed(
                    "render",
                    "revision-target-conflict",
                    "修订目标段落在页面中出现多次。",
                    field=f"revisions[{index}].current",
                )
            markdown = markdown.replace(revision["current"], revision["human_summary"], 1)
            authored_section_contexts[revision["section_id"]] = _section_validation_context(revision)
        if not markdown.endswith("\n"):
            markdown += "\n"

    context = payload.get("validation_context")
    assert isinstance(context, Mapping)
    merged_context = {
        "current_facts": list(context.get("current_facts", [])) if isinstance(context.get("current_facts", []), list) else context.get("current_facts"),
        "sections": dict(context.get("sections", {})) if isinstance(context.get("sections", {}), Mapping) else context.get("sections"),
    }
    if isinstance(merged_context["sections"], dict):
        merged_context["sections"].update(authored_section_contexts)
    validation = _candidate_validation(
        contract,
        markdown,
        evidence=payload.get("evidence"),
        context=merged_context,
        declared_boundary=payload.get("applicability_boundary"),
    )
    if validation["status"] != "passed":
        return {
            "errors": validation["errors"],
            "mode": mode,
            "operation": "render",
            "page_type": contract.page_type,
            "schema_version": HUMAN_PAGE_AUTHORING_SCHEMA_VERSION,
            "status": "failed",
            "validation": validation,
        }
    section_evidence = _section_evidence_document(contract, merged_context)
    section_evidence_bytes = (
        json.dumps(section_evidence, ensure_ascii=False, sort_keys=True, separators=(",", ":")) + "\n"
    ).encode("utf-8")
    return {
        "contract_version": HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
        "markdown": markdown,
        "markdown_sha256": _sha256_text(markdown),
        "mode": mode,
        "operation": "render",
        "page_type": contract.page_type,
        "schema_version": HUMAN_PAGE_AUTHORING_SCHEMA_VERSION,
        "section_evidence": section_evidence,
        "section_evidence_sha256": hashlib.sha256(section_evidence_bytes).hexdigest(),
        "source": {"path": str(source), "sha256": source_sha256} if source else None,
        "status": "ready",
        "validation": validation,
    }


_RECORD_TYPES = {"analysis", "change", "pitfall", "experiment", "session"}
_NAVIGATION_TYPES = {"INDEX", "WIKI", "RECORDS", "REFERENCES"}
_REFERENCE_URI_RE = re.compile(r"^[A-Za-z][A-Za-z0-9+.-]*:")


def _package_route(page_type: str) -> dict[str, Any]:
    if page_type in _RECORD_TYPES:
        return {
            "entrypoint": "record",
            "command": [
                "ckb.py",
                "record",
                "--out",
                "OUTPUT",
                "--kind",
                page_type,
                "--title",
                "TITLE",
                "--body",
                "BODY.md",
                "--from-pack",
                "PACK.json",
            ],
        }
    if page_type == "reference":
        return {
            "entrypoint": "reference",
            "command": ["ckb.py", "reference", "review", "--out", "OUTPUT", "--review", "REVIEW.json"],
        }
    if page_type == "feedback":
        return {
            "entrypoint": "feedback",
            "command": [
                "ckb.py",
                "feedback",
                "create",
                "--out",
                "OUTPUT",
                "--target",
                "TARGET",
                "--start-line",
                "START",
                "--end-line",
                "END",
                "--comment",
                "BODY.md",
                "--author",
                "AUTHOR",
            ],
        }
    if page_type == "learning-note":
        return {
            "entrypoint": "learning-note-generator",
            "plugin_command": "Ask about selection and save to daily learning note",
        }
    if page_type == "README":
        return {
            "entrypoint": "README-submit",
            "submission": "提交 BODY.md 供发布包 README 人工审阅；不写生成投影。",
        }
    if page_type in _NAVIGATION_TYPES:
        return {
            "entrypoint": f"{page_type}-generator",
            "command": ["ckb.py", "human-refresh", "--out", "OUTPUT"],
        }
    if page_type == "responsibility":
        return {
            "entrypoint": "responsibility-generator",
            "command": [
                "ckb.py",
                "review-pack",
                "--out",
                "OUTPUT",
                "--pack",
                "PACK_ID",
                "--review",
                "REVIEW.json",
            ],
        }
    raise RuntimeError(f"unrouted human page type: {page_type}")


def _staging_target(
    staging_dir: str | Path, workspace_root: str | Path
) -> tuple[Path | None, dict[str, Any] | None]:
    root = Path(workspace_root).resolve()
    target = Path(staging_dir)
    if not target.is_absolute():
        target = root / target
    target = target.resolve()
    if target == root or root not in target.parents:
        return None, _failed(
            "package",
            "path-outside-workspace",
            "staging 路径必须是 workspace_root 内的新目录。",
            path=str(target),
            workspace_root=str(root),
        )
    relative = target.relative_to(root)
    forbidden = {"human", "markdown", "machine"} & {part.casefold() for part in relative.parts}
    if forbidden or target.suffix.casefold() in {".sqlite", ".db"}:
        return None, _failed(
            "package",
            "managed-target-forbidden",
            "staging 包不得写入 human、markdown、machine 或 SQLite 受管路径。",
            path=str(target),
        )
    if target.exists():
        return None, _failed(
            "package",
            "staging-target-exists",
            "staging 包目录已存在；为避免覆盖，必须使用新目录。",
            path=str(target),
        )
    return target, None


def _portable_section_evidence(
    section_evidence: Mapping[str, Any],
    workspace_root: str | Path,
) -> tuple[dict[str, Any] | None, list[tuple[Path, str, str]], dict[str, Any] | None]:
    root = Path(workspace_root).resolve()
    packaged_sections: list[dict[str, Any]] = []
    copy_plan: list[tuple[Path, str, str]] = []
    for section in section_evidence.get("sections", []):
        if not isinstance(section, Mapping):
            continue
        section_id = str(section.get("section_id") or "")
        packaged_section = {
            "disclosure_level": str(section.get("disclosure_level") or ""),
            "heading": str(section.get("heading") or ""),
            "machine_evidence_refs": [],
            "section_id": section_id,
            "source_refs": [],
        }
        for field in ("source_refs", "machine_evidence_refs"):
            values = section.get(field, [])
            if not isinstance(values, list):
                continue
            for index, item in enumerate(values):
                if not isinstance(item, Mapping):
                    continue
                target = str(item.get("target") or "").strip()
                is_windows_drive = bool(re.match(r"^[A-Za-z]:[\\/]", target))
                if _REFERENCE_URI_RE.match(target) and not is_windows_drive:
                    packaged_section[field].append({**dict(item), "target_basis": "uri"})
                    continue
                candidate = Path(target)
                if not candidate.is_absolute():
                    candidate = root / candidate
                candidate = candidate.resolve()
                if candidate != root and root not in candidate.parents:
                    return None, [], _failed(
                        "package",
                        "reference-target-outside-workspace",
                        "章节来源或机器证据路径越过 workspace_root。",
                        field=f"section_evidence.{section_id}.{field}[{index}]",
                        target=target,
                    )
                if not candidate.is_file():
                    return None, [], _failed(
                        "package",
                        "reference-target-not-found",
                        "章节来源或机器证据路径不是可读取文件。",
                        field=f"section_evidence.{section_id}.{field}[{index}]",
                        target=target,
                    )
                expected = str(item.get("sha256") or "").strip().casefold()
                if not _SHA256_RE.fullmatch(expected):
                    return None, [], _failed(
                        "package",
                        "reference-target-sha256-missing",
                        "文件型来源或机器证据引用必须提供小写 SHA-256。",
                        field=f"section_evidence.{section_id}.{field}[{index}].sha256",
                        target=target,
                    )
                actual = hashlib.sha256(candidate.read_bytes()).hexdigest()
                if actual != expected:
                    return None, [], _failed(
                        "package",
                        "reference-target-drift",
                        "章节来源或机器证据文件与声明 SHA-256 不一致。",
                        field=f"section_evidence.{section_id}.{field}[{index}]",
                        target=target,
                        expected_sha256=expected,
                        actual_sha256=actual,
                    )
                portable_target = Path("evidence") / expected / candidate.name
                portable_value = {
                    **dict(item),
                    "original_target": target,
                    "package_owned": True,
                    "target": portable_target.as_posix(),
                    "target_basis": "manifest-parent",
                }
                packaged_section[field].append(portable_value)
                copy_plan.append((candidate, portable_target.as_posix(), expected))
        for field in ("source_refs", "machine_evidence_refs"):
            packaged_section[field] = sorted(
                packaged_section[field],
                key=lambda item: (
                    str(item.get("target") or ""),
                    str(item.get("kind") or ""),
                    str(item.get("purpose") or ""),
                    str(item.get("sha256") or ""),
                ),
            )
        packaged_sections.append(packaged_section)
    portable = {
        "schema_version": 2,
        "target_resolution": {
            "file_target_basis": "manifest-parent",
            "package_owned_directory": "evidence",
            "uri_target_basis": "uri",
        },
        "sections": packaged_sections,
    }
    unique_plan = {
        (target, digest): (source, target, digest)
        for source, target, digest in copy_plan
    }
    return portable, [unique_plan[key] for key in sorted(unique_plan)], None


def package_page_author(
    payload: Mapping[str, Any],
    staging_dir: str | Path,
    *,
    workspace_root: str | Path = ".",
) -> dict[str, Any]:
    """Write only a validated ``body.md`` and routing ``manifest.json``."""

    rendered = render_page_author(payload, workspace_root=workspace_root)
    if rendered.get("status") != "ready":
        result = dict(rendered)
        result["operation"] = "package"
        return result
    section_evidence = rendered.get("section_evidence", {})
    if not isinstance(section_evidence, Mapping):
        return _failed("package", "section-evidence-invalid", "render 未返回规范化章节证据引用。")
    packaged_section_evidence, copy_plan, failure = _portable_section_evidence(
        section_evidence, workspace_root
    )
    if failure:
        return failure
    assert packaged_section_evidence is not None
    target, failure = _staging_target(staging_dir, workspace_root)
    if failure:
        return failure
    assert target is not None
    markdown = str(rendered["markdown"])
    markdown_sha256 = str(rendered["markdown_sha256"])
    route = _package_route(str(rendered["page_type"]))
    section_evidence_bytes = (
        json.dumps(
            packaged_section_evidence,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        )
        + "\n"
    ).encode("utf-8")
    section_evidence_sha256 = hashlib.sha256(section_evidence_bytes).hexdigest()
    evidence_paths = sorted(target_value for _source, target_value, _digest in copy_plan)
    manifest = {
        "body": {"path": "body.md", "sha256": markdown_sha256},
        "contract_version": HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
        "direct_projection_write": False,
        "mode": rendered["mode"],
        "next_entry": route,
        "page_type": rendered["page_type"],
        "registry_sha256": human_page_template_registry_sha256(),
        "schema_version": HUMAN_PAGE_AUTHORING_SCHEMA_VERSION,
        "package_owned_paths": ["body.md", *evidence_paths, "manifest.json"],
        "section_evidence": packaged_section_evidence,
        "section_evidence_sha256": section_evidence_sha256,
        "source": rendered.get("source"),
        "status": "staged",
        "validation": rendered["validation"],
    }
    body_bytes = markdown.encode("utf-8")
    manifest_bytes = (json.dumps(manifest, ensure_ascii=False, indent=2, sort_keys=True) + "\n").encode("utf-8")
    temporary = target.with_name(f".{target.name}.tmp-{markdown_sha256[:12]}")
    if temporary.exists():
        return _failed(
            "package",
            "staging-temporary-exists",
            "staging 临时目录已存在，未覆盖其内容。",
            path=str(temporary),
        )
    try:
        temporary.mkdir(parents=True)
        (temporary / "body.md").write_bytes(body_bytes)
        for source_path, relative_target, expected_sha256 in copy_plan:
            evidence_target = temporary / relative_target
            evidence_target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(source_path, evidence_target)
            if hashlib.sha256(evidence_target.read_bytes()).hexdigest() != expected_sha256:
                raise OSError(f"staged evidence hash verification failed: {relative_target}")
        (temporary / "manifest.json").write_bytes(manifest_bytes)
        if hashlib.sha256((temporary / "body.md").read_bytes()).hexdigest() != markdown_sha256:
            raise OSError("staged body hash verification failed")
        os.replace(temporary, target)
    except OSError as exc:
        if temporary.exists():
            shutil.rmtree(temporary)
        return _failed("package", "staging-write-failed", f"staging 包写入失败：{exc}", path=str(target))

    manifest_sha256 = hashlib.sha256((target / "manifest.json").read_bytes()).hexdigest()
    reopened_manifest = json.loads((target / "manifest.json").read_text(encoding="utf-8"))
    if reopened_manifest != manifest:
        return _failed("package", "staging-reopen-failed", "staging manifest 重开后内容不一致。")
    for _source_path, relative_target, expected_sha256 in copy_plan:
        reopened_evidence = target / relative_target
        if not reopened_evidence.is_file() or hashlib.sha256(reopened_evidence.read_bytes()).hexdigest() != expected_sha256:
            return _failed(
                "package",
                "staging-evidence-reopen-failed",
                "staging 机器证据副本重开后缺失或哈希不一致。",
                target=relative_target,
            )
    return {
        "artifacts": {
            "body": str(target / "body.md"),
            "evidence": [str(target / value) for value in evidence_paths],
            "manifest": str(target / "manifest.json"),
        },
        "body_sha256": markdown_sha256,
        "contract_version": HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
        "manifest_sha256": manifest_sha256,
        "mode": rendered["mode"],
        "next_entry": route,
        "operation": "package",
        "page_type": rendered["page_type"],
        "schema_version": HUMAN_PAGE_AUTHORING_SCHEMA_VERSION,
        "section_evidence_sha256": section_evidence_sha256,
        "status": "ready",
    }


def load_authoring_input(path: Path) -> Mapping[str, Any]:
    value = json.loads(path.read_text(encoding="utf-8-sig"))
    if not isinstance(value, Mapping):
        raise ValueError("page-author input must be a JSON object")
    return value

"""Output-local human page template proposals with deterministic review gates.

The store is deliberately separate from the built-in template registry and the
human-page projection pipeline.  Submitting a document can only create a
pending proposal; later human-audit operations are the sole activation path.
"""

