}
_BUDGET_FIELDS = {"key_entities", "source_links", "total_characters"}
_COUNT_BUDGET_FIELDS = {"counting_rule", "maximum", "minimum", "overflow_action", "scope"}
_CHARACTER_BUDGET_FIELDS = {"maximum", "overflow_action"}
_SECTION_LENGTH_FIELDS = {
